(3999611, 571732, 49109, '<td valign="top">a bit too much of the trees and shady ground for my taste, had cropped closer</td>', 'a bit too much of the trees and shady ground for my taste, had cropped closer', '2007-08-15 06:23:27.000000', NULL, 1),
(3999615, 569188, 49109, '<td valign="top">could be a little more saturated, composition is too half-and-half. border distracts a bit.</td>', 'could be a little more saturated, composition is too half-and-half. border distracts a bit.', '2007-08-15 06:24:36.000000', NULL, 1),
