(3999621, 569876, 49109, '<td valign="top">I''d be interested on why you post these images. What do you want to proof? Or do you just want to spoil our fun with DPC? If you have something to share, post in the forums, might start an interesting discussion.</td>', 'I''d be interested on why you post these images. What do you want to proof? Or do you just want to spoil our fun with DPC? If you have something to share, post in the forums, might start an interesting discussion.', '2007-08-15 06:30:41.000000', NULL, 1),
(3999624, 571796, 49109, '<td valign="top">crop at left is too tight, image is too dull overall.</td>', 'crop at left is too tight, image is too dull overall.', '2007-08-15 06:31:39.000000', NULL, 1),
(3999679, 571970, 82534, '<td valign="top">The softness of the building is really nice, but the sky came out a bit grainy and it seems to detract from the beauty of the old barn.</td>', 'The softness of the building is really nice, but the sky came out a bit grainy and it seems to detract from the beauty of the old barn.', '2007-08-15 07:07:41.000000', NULL, 1),
(3999680, 570031, 82534, '<td valign="top">Wonderful capture from above the clouds.  A shot I''ve always wanted to capture around here, but never was at the right time or place with my camera.</td>', 'Wonderful capture from above the clouds.  A shot I''ve always wanted to capture around here, but never was at the right time or place with my camera.', '2007-08-15 07:08:24.000000', NULL, 1),
(3999682, 570093, 82534, '<td valign="top">I like the arches of the bridge, but the foreground is a bit distracting on the left side of the frame.</td>', 'I like the arches of the bridge, but the foreground is a bit distracting on the left side of the frame.', '2007-08-15 07:09:04.000000', NULL, 1),
(3999692, 569119, 82534, '<td valign="top">Amazing capture of a rainbow over a field.  Love the moody clouds too!</td>', 'Amazing capture of a rainbow over a field.  Love the moody clouds too!', '2007-08-15 07:13:47.000000', NULL, 1),
(3999695, 568951, 82534, '<td valign="top">I''m unclear how this shot fits with the rural theme.  Pretty colors either way.</td>', 'I''m unclear how this shot fits with the rural theme.  Pretty colors either way.', '2007-08-15 07:15:07.000000', NULL, 1),
(3999696, 571037, 82534, '<td valign="top">What a beautiful backdrop for a farmer!  I wish my field overlooked distant hills and a lake!</td>', 'What a beautiful backdrop for a farmer!  I wish my field overlooked distant hills and a lake!', '2007-08-15 07:16:25.000000', NULL, 1),
(3999697, 571777, 82534, '<td valign="top">Great shot, but I get the feeling you entered this in the wrong challenge (Rural instead of Urban...)</td>', 'Great shot, but I get the feeling you entered this in the wrong challenge (Rural instead of Urban...)', '2007-08-15 07:17:46.000000', NULL, 1),
(3999700, 571678, 81810, '<td valign="top">What a beautiful scene! I like the softness of the back ground and the perfect shadow of the dears. Great work!</td>', 'What a beautiful scene! I like the softness of the back ground and the perfect shadow of the dears. Great work!', '2007-08-15 07:18:24.000000', NULL, 1),
(3999701, 570358, 82534, '<td valign="top">This capture has such a dream like quality to it.  Very nice.</td>', 'This capture has such a dream like quality to it.  Very nice.', '2007-08-15 07:18:26.000000', NULL, 1),
(3999702, 571860, 82534, '<td valign="top">The border is somewhat distracting on this image.  Plus, the greens look a little over-saturated.</td>', 'The border is somewhat distracting on this image.  Plus, the greens look a little over-saturated.', '2007-08-15 07:19:10.000000', NULL, 1),
(3999704, 571397, 82534, '<td valign="top">Great movement captured in the tail!</td>', 'Great movement captured in the tail!', '2007-08-15 07:19:28.000000', NULL, 1),
(3999706, 571645, 82534, '<td valign="top">Great foreground.  The purple haze along the horizon is a bit distracting for me.</td>', 'Great foreground.  The purple haze along the horizon is a bit distracting for me.', '2007-08-15 07:20:28.000000', NULL, 1),
(3999708, 569261, 52572, '<td valign="top">fantastic. Great capture of light beam<br/>it''s perfect! *fav*</td>', 'fantastic. Great capture of light beamit''s perfect! *fav*', '2007-08-15 07:22:11.000000', NULL, 1),
(3999842, 569876, 53147, '<td valign="top">these entries just irritate me</td>', 'these entries just irritate me', '2007-08-15 08:13:31.000000', NULL, 1),
(3999847, 571846, 53147, '<td valign="top">I really like this image. Gave it a 9 last night before going to bed. Coming back around to comment I still really like this but I think that the color tones used could have been better. Kind of has a green hue going on in my monitor where I think a maybe more true sepia could have been better. Anyway, love the comp, simple and entertaining. Good luck!</td>', 'I really like this image. Gave it a 9 last night before going to bed. Coming back around to comment I still really like this but I think that the color tones used could have been better. Kind of has a green hue going on in my monitor where I think a maybe more true sepia could have been better. Anyway, love the comp, simple and entertaining. Good luck!', '2007-08-15 08:15:30.000000', NULL, 1),
(3999848, 571442, 77543, '<td valign="top">I''m not sure this works as a silhouette. I''d like to see more detail.</td>', 'I''m not sure this works as a silhouette. I''d like to see more detail.', '2007-08-15 08:16:06.000000', NULL, 1),
(3999849, 568315, 53147, '<td valign="top">Yeah baby. This one rocks from the moment it opened on my screen. Awesome image. Hope this scores well for you.</td>', 'Yeah baby. This one rocks from the moment it opened on my screen. Awesome image. Hope this scores well for you.', '2007-08-15 08:16:08.000000', NULL, 1),
(3999851, 571477, 53147, '<td valign="top">Like a stunning postcard. Great scene, amazing colors, wonderful detail. Would be surprised to not see this with a ribbon on it come next TUesday. Bumping up to 10.</td>', 'Like a stunning postcard. Great scene, amazing colors, wonderful detail. Would be surprised to not see this with a ribbon on it come next TUesday. Bumping up to 10.', '2007-08-15 08:17:07.000000', NULL, 1),
(3999855, 571876, 53147, '<td valign="top">It''s whats for dinner. Great shot. I am a sucker for a good cow pic. Great colors and very pleasing image.</td>', 'It''s whats for dinner. Great shot. I am a sucker for a good cow pic. Great colors and very pleasing image.', '2007-08-15 08:18:24.000000', NULL, 1),
(3999872, 570303, 82534, '<td valign="top">I have to say -- with "ears" in the title, I expected corn!</td>', 'I have to say -- with "ears" in the title, I expected corn!', '2007-08-15 08:34:48.000000', NULL, 1),
(3999887, 572005, 38509, '<td valign="top">this one is really cool, excellent ! 9</td>', 'this one is really cool, excellent ! 9', '2007-08-15 08:42:53.000000', NULL, 1),
(3999903, 571846, 52169, '<td valign="top">Perfect,Perfect,Perfect,Perfect,Perfect-10 and a fav</td>', 'Perfect,Perfect,Perfect,Perfect,Perfect-10 and a fav', '2007-08-15 08:51:46.000000', NULL, 1),
