(4003718, 571379, 67258, '<td valign="top">This doesn''t meet with my idea of a rural landscape.  That said, you have made an interesting find.</td>', 'This doesn''t meet with my idea of a rural landscape.  That said, you have made an interesting find.', '2007-08-16 09:38:24.000000', NULL, 1),
(4003720, 571362, 67258, '<td valign="top">Your exposure for the water and sky is fine, but the rest of the image is much too dark, meaning that detail is lost.</td>', 'Your exposure for the water and sky is fine, but the rest of the image is much too dark, meaning that detail is lost.', '2007-08-16 09:39:30.000000', NULL, 1),
