(4005694, 571788, 53892, '<td valign="top">that looks really like an old fashioned photo</td>', 'that looks really like an old fashioned photo', '2007-08-17 00:05:42.000000', NULL, 1),
(4005723, 571103, 53892, '<td valign="top">this would make an awesome crop too!</td>', 'this would make an awesome crop too!', '2007-08-17 00:18:26.000000', NULL, 1),
