(4006856, 571846, 79562, '<td valign="top">this shot really establishes a strong mood - not your typical landscap cliche.  great!</td>', 'this shot really establishes a strong mood - not your typical landscap cliche.  great!', '2007-08-17 14:47:18.000000', NULL, 1),
