(4006872, 571380, 76932, '<td valign="top">nice colours</td>', 'nice colours', '2007-08-17 14:52:26.000000', NULL, 1),
(4006876, 570974, 76932, '<td valign="top">great atmosphere</td>', 'great atmosphere', '2007-08-17 14:53:16.000000', NULL, 1),
