(4006885, 572007, 76932, '<td valign="top">great one, beautiful light and tones</td>', 'great one, beautiful light and tones', '2007-08-17 14:56:28.000000', NULL, 1),
(4006889, 571846, 56880, '<td valign="top">Hey Joe, where ya going with that gun in your hand?</td>', 'Hey Joe, where ya going with that gun in your hand?', '2007-08-17 14:56:48.000000', NULL, 1),
(4006901, 570451, 79562, '<td valign="top">great crop - wonderful surreal touch!</td>', 'great crop - wonderful surreal touch!', '2007-08-17 15:00:06.000000', NULL, 1),
(4006902, 572004, 79562, '<td valign="top">gorgeous - bravo!</td>', 'gorgeous - bravo!', '2007-08-17 15:00:32.000000', NULL, 1),
(4006908, 570818, 56441, '<td valign="top">Theres something to the left that would have been best cropped out, other than that very nice!</td>', 'Theres something to the left that would have been best cropped out, other than that very nice!', '2007-08-17 15:01:55.000000', NULL, 1),
(4006918, 570243, 56441, '<td valign="top">I find the out of focus grass at the front distracting.</td>', 'I find the out of focus grass at the front distracting.', '2007-08-17 15:03:53.000000', NULL, 1),
(4006935, 570969, 56441, '<td valign="top">I wish the wire across the center of the picture wasnt there and it was just the side fence.</td>', 'I wish the wire across the center of the picture wasnt there and it was just the side fence.', '2007-08-17 15:07:00.000000', NULL, 1),
(4006942, 571731, 56441, '<td valign="top">Oh wow, this is amazing, well done!</td>', 'Oh wow, this is amazing, well done!', '2007-08-17 15:08:37.000000', NULL, 1),
(4006954, 570915, 56441, '<td valign="top">Is that Bamboo?</td>', 'Is that Bamboo?', '2007-08-17 15:11:29.000000', NULL, 1),
(4006979, 571375, 82817, '<td valign="top">Love the double rainbow and the saturated colors. The clouds are quite dramatic as well. Well done!</td>', 'Love the double rainbow and the saturated colors. The clouds are quite dramatic as well. Well done!', '2007-08-17 15:18:51.000000', NULL, 1),
(4006984, 569421, 82817, '<td valign="top">I like the concept but I wish there was more depth of field.</td>', 'I like the concept but I wish there was more depth of field.', '2007-08-17 15:19:37.000000', NULL, 1),
(4006989, 571860, 82817, '<td valign="top">I love the composition and the colors in the foreground. It looks a tad out of focus. I am very distracted by the yellow on the inside border.</td>', 'I love the composition and the colors in the foreground. It looks a tad out of focus. I am very distracted by the yellow on the inside border.', '2007-08-17 15:21:45.000000', NULL, 1),
(4006993, 571864, 82817, '<td valign="top">Very dramatic! The deep blues and purples are wonderful.</td>', 'Very dramatic! The deep blues and purples are wonderful.', '2007-08-17 15:24:07.000000', NULL, 1),
(4006997, 571946, 82817, '<td valign="top">Nicely executed. I like the composition and how the branches point to the sunset.</td>', 'Nicely executed. I like the composition and how the branches point to the sunset.', '2007-08-17 15:25:50.000000', NULL, 1),
(4006998, 571731, 82817, '<td valign="top">Wonderful! I love this shot!</td>', 'Wonderful! I love this shot!', '2007-08-17 15:26:28.000000', NULL, 1),
(4007001, 568189, 82817, '<td valign="top">The branches and leaves are a bit distracting but a nice shot of the rooster.</td>', 'The branches and leaves are a bit distracting but a nice shot of the rooster.', '2007-08-17 15:27:56.000000', NULL, 1),
(4007004, 570937, 82817, '<td valign="top">I would have liked to see more depth of field.</td>', 'I would have liked to see more depth of field.', '2007-08-17 15:29:35.000000', NULL, 1),
(4007006, 570093, 82817, '<td valign="top">A clear reflection would have made the shot spectacular.</td>', 'A clear reflection would have made the shot spectacular.', '2007-08-17 15:31:17.000000', NULL, 1),
(4007009, 571442, 82817, '<td valign="top">Very moody though I wish it were straighted vertically.</td>', 'Very moody though I wish it were straighted vertically.', '2007-08-17 15:32:25.000000', NULL, 1),
(4007014, 571354, 82817, '<td valign="top">I love zoooooooooooom shots. Great colors!</td>', 'I love zoooooooooooom shots. Great colors!', '2007-08-17 15:34:17.000000', NULL, 1),
(4007018, 570273, 82817, '<td valign="top">Too bad everything is tilted to the right. Great shot otherwise.</td>', 'Too bad everything is tilted to the right. Great shot otherwise.', '2007-08-17 15:35:34.000000', NULL, 1),
(4007022, 571993, 82817, '<td valign="top">I am not clear about what the actual subject matter is. the noise on the roof lines is distracting.</td>', 'I am not clear about what the actual subject matter is. the noise on the roof lines is distracting.', '2007-08-17 15:37:21.000000', NULL, 1),
(4007023, 571908, 82817, '<td valign="top">I like the bottom half of the photograph but the top doesn''t work for me.</td>', 'I like the bottom half of the photograph but the top doesn''t work for me.', '2007-08-17 15:39:06.000000', NULL, 1),
(4007025, 569347, 82817, '<td valign="top">Looks pretty much like a snapshot.</td>', 'Looks pretty much like a snapshot.', '2007-08-17 15:39:47.000000', NULL, 1),
(4007027, 570451, 82817, '<td valign="top">This took me by surprise. Thanks! It has the feel of rural 1920''s or 30''s.</td>', 'This took me by surprise. Thanks! It has the feel of rural 1920''s or 30''s.', '2007-08-17 15:41:00.000000', NULL, 1),
(4007030, 570498, 82817, '<td valign="top">Nice snapshot but nothing of real interest to hold my attention.</td>', 'Nice snapshot but nothing of real interest to hold my attention.', '2007-08-17 15:41:44.000000', NULL, 1),
(4007033, 571874, 82817, '<td valign="top">I am not sure I like the white trees but it is what caught my eye in the first place. Lovely composition.</td>', 'I am not sure I like the white trees but it is what caught my eye in the first place. Lovely composition.', '2007-08-17 15:43:45.000000', NULL, 1),
(4007039, 571148, 82817, '<td valign="top">I get the sense of strong winds from the twisted barn.</td>', 'I get the sense of strong winds from the twisted barn.', '2007-08-17 15:45:11.000000', NULL, 1),
(4007043, 568826, 82817, '<td valign="top">The roof is a bit bright and distracting but it creates movement.</td>', 'The roof is a bit bright and distracting but it creates movement.', '2007-08-17 15:46:05.000000', NULL, 1),
(4007048, 571799, 82817, '<td valign="top">Worth visiting again.</td>', 'Worth visiting again.', '2007-08-17 15:47:15.000000', NULL, 1),
(4007049, 570823, 82817, '<td valign="top">Looks kinda fuzzy except for the yellowish building.</td>', 'Looks kinda fuzzy except for the yellowish building.', '2007-08-17 15:48:03.000000', NULL, 1),
(4007051, 569806, 82817, '<td valign="top">Seems a tad out of focus though an interesting perspective.</td>', 'Seems a tad out of focus though an interesting perspective.', '2007-08-17 15:49:04.000000', NULL, 1),
(4007054, 568951, 82817, '<td valign="top">Beautiful colors and setting but not clearly focused.</td>', 'Beautiful colors and setting but not clearly focused.', '2007-08-17 15:50:01.000000', NULL, 1),
(4007057, 571924, 82817, '<td valign="top">I would have liked more room in front of the carts to get more perspective on the trail ahead.</td>', 'I would have liked more room in front of the carts to get more perspective on the trail ahead.', '2007-08-17 15:51:16.000000', NULL, 1),
(4007060, 568903, 82817, '<td valign="top">Depth of field and focus could be much better and a different angle of the Zebra.</td>', 'Depth of field and focus could be much better and a different angle of the Zebra.', '2007-08-17 15:52:31.000000', NULL, 1),
(4007062, 571116, 82817, '<td valign="top">A hard shot to get all elements in balance for saturation and contrast. Nice work.</td>', 'A hard shot to get all elements in balance for saturation and contrast. Nice work.', '2007-08-17 15:53:42.000000', NULL, 1),
(4007063, 571832, 82817, '<td valign="top">Suits me fine. Love the colors and the suit. A bit more of a vanishing point and viola.</td>', 'Suits me fine. Love the colors and the suit. A bit more of a vanishing point and viola.', '2007-08-17 15:54:44.000000', NULL, 1),
(4007065, 569892, 82817, '<td valign="top">Snapshot with nice light.</td>', 'Snapshot with nice light.', '2007-08-17 15:55:11.000000', NULL, 1),
(4007077, 569194, 82817, '<td valign="top">It is so rural they forgot the rails. The utility post ruins the shot for me. There might not be anything one can do about that.</td>', 'It is so rural they forgot the rails. The utility post ruins the shot for me. There might not be anything one can do about that.', '2007-08-17 15:59:49.000000', NULL, 1),
(4007081, 570035, 82817, '<td valign="top">There is a lot going on in this shot. Buildings, lights, and lightening. Almost looks like two photos put together.</td>', 'There is a lot going on in this shot. Buildings, lights, and lightening. Almost looks like two photos put together.', '2007-08-17 16:01:38.000000', NULL, 1),
(4007085, 571788, 82817, '<td valign="top">High noon is the problem here. Too much light and no clear subject.</td>', 'High noon is the problem here. Too much light and no clear subject.', '2007-08-17 16:02:38.000000', NULL, 1),
(4007089, 569883, 82817, '<td valign="top">Great colors in the sky and the water.</td>', 'Great colors in the sky and the water.', '2007-08-17 16:03:22.000000', NULL, 1),
(4007093, 571777, 82817, '<td valign="top">Rural? Looks a bit posed.</td>', 'Rural? Looks a bit posed.', '2007-08-17 16:04:13.000000', NULL, 1),
(4007100, 570318, 82817, '<td valign="top">Is that a madding crowd in yonder field? I like it but I am not compelled to look anywhere in particular.</td>', 'Is that a madding crowd in yonder field? I like it but I am not compelled to look anywhere in particular.', '2007-08-17 16:06:58.000000', NULL, 1),
(4007105, 571686, 82817, '<td valign="top">A fixer-upper! Price just reduced! Wonderful mountain views! I love the sepia tone and the composition.</td>', 'A fixer-upper! Price just reduced! Wonderful mountain views! I love the sepia tone and the composition.', '2007-08-17 16:08:37.000000', NULL, 1),
(4007110, 571086, 82817, '<td valign="top">I am not sure about what to look at here. I love the green though a bit over exposed and the water is nice too.</td>', 'I am not sure about what to look at here. I love the green though a bit over exposed and the water is nice too.', '2007-08-17 16:09:51.000000', NULL, 1),
(4007112, 569214, 82817, '<td valign="top">What could be more rural then hay? Take a look at some of the others and I don''t mean it harshly, get some perspective, in the photograph that is.</td>', 'What could be more rural then hay? Take a look at some of the others and I don''t mean it harshly, get some perspective, in the photograph that is.', '2007-08-17 16:11:18.000000', NULL, 1),
(4007118, 570248, 82817, '<td valign="top">Green acres is the place to be! Hey, what''s with the yellow acres on the next rise? love the colors of the landscape but the sky needs help. Good place to shoot again.</td>', 'Green acres is the place to be! Hey, what''s with the yellow acres on the next rise? love the colors of the landscape but the sky needs help. Good place to shoot again.', '2007-08-17 16:12:50.000000', NULL, 1),
(4007122, 570787, 82817, '<td valign="top">I don''t think of golf courses as rural but this one might be. Looks a bit like a snapshot.</td>', 'I don''t think of golf courses as rural but this one might be. Looks a bit like a snapshot.', '2007-08-17 16:13:59.000000', NULL, 1),
(4007125, 570166, 82817, '<td valign="top">Toooooo telephoto for me. I do like the concept.</td>', 'Toooooo telephoto for me. I do like the concept.', '2007-08-17 16:14:43.000000', NULL, 1),
(4007127, 569188, 82817, '<td valign="top">Too bad the sky was not bluer.</td>', 'Too bad the sky was not bluer.', '2007-08-17 16:15:11.000000', NULL, 1),
(4007132, 571757, 82817, '<td valign="top">Maybe a bit too much color saturation and I wish the front canyon wall had some detail.</td>', 'Maybe a bit too much color saturation and I wish the front canyon wall had some detail.', '2007-08-17 16:16:17.000000', NULL, 1),
(4007133, 570472, 82817, '<td valign="top">Nice leaves. The flowers might have been the subject but the leaves have the focal point.</td>', 'Nice leaves. The flowers might have been the subject but the leaves have the focal point.', '2007-08-17 16:17:08.000000', NULL, 1),
(4007135, 571762, 82817, '<td valign="top">Another over saturated canyon shot with missing detail on the wonderful tree in the left foreground.</td>', 'Another over saturated canyon shot with missing detail on the wonderful tree in the left foreground.', '2007-08-17 16:18:07.000000', NULL, 1),
(4007136, 569751, 82817, '<td valign="top">The tree on the left is distracting.</td>', 'The tree on the left is distracting.', '2007-08-17 16:18:44.000000', NULL, 1),
(4007189, 568315, 52169, '<td valign="top">Perfect for this challenge! A postcard from the country! 10</td>', 'Perfect for this challenge! A postcard from the country! 10', '2007-08-17 16:32:12.000000', NULL, 1),
(4007198, 570325, 66201, '<td valign="top">One of my favs in this challenge.</td>', 'One of my favs in this challenge.', '2007-08-17 16:35:46.000000', NULL, 1),
(4007202, 571915, 66201, '<td valign="top">Love the almost desat look to this.</td>', 'Love the almost desat look to this.', '2007-08-17 16:37:08.000000', NULL, 1),
(4007206, 570969, 66201, '<td valign="top">The oof horizontal wire is very distracting. It cuts the image in half. Otherwise a simple, elegant capture.</td>', 'The oof horizontal wire is very distracting. It cuts the image in half. Otherwise a simple, elegant capture.', '2007-08-17 16:38:03.000000', NULL, 1),
(4007210, 571939, 66201, '<td valign="top">The flamingo sky looks off to me: seems as if a colour filter has been applied, causing the redness in the soil patches.</td>', 'The flamingo sky looks off to me: seems as if a colour filter has been applied, causing the redness in the soil patches.', '2007-08-17 16:39:08.000000', NULL, 1),
(4007212, 571477, 66201, '<td valign="top">A true calendar shot! Very pretty.</td>', 'A true calendar shot! Very pretty.', '2007-08-17 16:39:36.000000', NULL, 1),
(4007226, 571955, 66201, '<td valign="top">I think your Contrasts were too strong: the shadows are very heavy and the roofing is blown out. A lovely setting for your shot.</td>', 'I think your Contrasts were too strong: the shadows are very heavy and the roofing is blown out. A lovely setting for your shot.', '2007-08-17 16:44:07.000000', NULL, 1),
(4007239, 571862, 63398, '<td valign="top">DNMC IMO</td>', 'DNMC IMO', '2007-08-17 16:47:08.000000', NULL, 1),
(4007243, 571939, 52472, '<td valign="top">The colours are a bit oversaturated for my taste. Mainly the greens, the background is fine because of its smoothness.</td>', 'The colours are a bit oversaturated for my taste. Mainly the greens, the background is fine because of its smoothness.', '2007-08-17 16:47:21.000000', NULL, 1),
(4007248, 571762, 63398, '<td valign="top">Lovely shot, but DNMC-NOT rural</td>', 'Lovely shot, but DNMC-NOT rural', '2007-08-17 16:48:18.000000', NULL, 1),
(4007326, 571969, 52472, '<td valign="top">Very nice composition and perfect lighting. It''s one of my favourites. 10</td>', 'Very nice composition and perfect lighting. It''s one of my favourites. 10', '2007-08-17 17:19:18.000000', NULL, 1),
(4007338, 571142, 52472, '<td valign="top">Excellent! It''s what a rural idyll looks like. 10</td>', 'Excellent! It''s what a rural idyll looks like. 10', '2007-08-17 17:22:36.000000', NULL, 1),
(4007352, 569261, 63398, '<td valign="top">I really have a dilemma with this as it really doesn''t technically fit the description of rural. A truly awesome composition and capture and a wonderful scene. I''m giving it a 6 because of it, though in a Free Study I''d have gone higher. The 6 is strictly on the shot''s merits but IMNSHO, DNMC.<br/> <br/>Upon reflection, and being honest, it''s no less rural than my entry, and in the spirit of fair play, you talented b*stard, I''m bumping this to an 8.</td>', 'I really have a dilemma with this as it really doesn''t technically fit the description of rural. A truly awesome composition and capture and a wonderful scene. I''m giving it a 6 because of it, though in a Free Study I''d have gone higher. The 6 is strictly on the shot''s merits but IMNSHO, DNMC. Upon reflection, and being honest, it''s no less rural than my entry, and in the spirit of fair play, you talented b*stard, I''m bumping this to an 8.', '2007-08-17 17:25:31.000000', NULL, 1),
(4007355, 570318, 67258, '<td valign="top">Wonderful pastoral scene, beautifully observed.  Yorkshire?</td>', 'Wonderful pastoral scene, beautifully observed.  Yorkshire?', '2007-08-17 17:27:22.000000', NULL, 1),
(4007361, 570937, 67258, '<td valign="top">Ah, Cornwall!  I didn''t get down this summer, and viewing this is making me wish I had...:¬(  A really well composed and exposed photograph of one ofmy favorite parts of the country. (And this is where I discover it is really Australia or somewhere and am made to feel a right chump!).  Lovely photo, with nothing I would want changed.</td>', 'Ah, Cornwall!  I didn''t get down this summer, and viewing this is making me wish I had...:¬(  A really well composed and exposed photograph of one ofmy favorite parts of the country. (And this is where I discover it is really Australia or somewhere and am made to feel a right chump!).  Lovely photo, with nothing I would want changed.', '2007-08-17 17:30:52.000000', NULL, 1),
(4007406, 569876, 70181, '<td valign="top">Stupendous.  Amazing.  Fantabulous.  Absolutely gorgeous.  Complicated, yet simple.  Classic, yet contemporary.  Haphazard, yet controlled.  The greatest photo ever on DPC.  Like something out of a dream.  Beautiful colors.  Fabulous composition.  Perfect depth of field.  I love it.  Instant favorite.  Should be on the cover of a magazine.  Since I''m not able to give this a 20, I must refrain from voting.</td>', 'Stupendous.  Amazing.  Fantabulous.  Absolutely gorgeous.  Complicated, yet simple.  Classic, yet contemporary.  Haphazard, yet controlled.  The greatest photo ever on DPC.  Like something out of a dream.  Beautiful colors.  Fabulous composition.  Perfect depth of field.  I love it.  Instant favorite.  Should be on the cover of a magazine.  Since I''m not able to give this a 20, I must refrain from voting.', '2007-08-17 17:49:40.000000', NULL, 1),
(4007416, 568343, 67258, '<td valign="top">The land of Valar?  Beautiful!</td>', 'The land of Valar?  Beautiful!', '2007-08-17 17:56:03.000000', NULL, 1),
(4007752, 571825, 81852, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2007-08-17 20:47:29.000000', NULL, 1),
(4007755, 571674, 81852, '<td valign="top">I like the idea, but to me, the hay bail just sort of blends right into the ground.  Might have worked if the color was there to create a contrast. Nice photo though.</td>', 'I like the idea, but to me, the hay bail just sort of blends right into the ground.  Might have worked if the color was there to create a contrast. Nice photo though.', '2007-08-17 20:49:28.000000', NULL, 1),
(4007756, 569301, 81852, '<td valign="top">Very pretty!</td>', 'Very pretty!', '2007-08-17 20:50:32.000000', NULL, 1),
(4007761, 571103, 81852, '<td valign="top">Cute!</td>', 'Cute!', '2007-08-17 20:53:21.000000', NULL, 1),
(4007763, 570453, 81852, '<td valign="top">This is so nice! The colors are so vibrant. I really like it. Good job!</td>', 'This is so nice! The colors are so vibrant. I really like it. Good job!', '2007-08-17 20:54:36.000000', NULL, 1),
(4007765, 570031, 45475, '<td valign="top">Excellent. Great view, worth the hike up there I''m sure.</td>', 'Excellent. Great view, worth the hike up there I''m sure.', '2007-08-17 20:55:58.000000', NULL, 1),
(4007766, 571906, 81852, '<td valign="top">Wow! That red just jumps out at you!</td>', 'Wow! That red just jumps out at you!', '2007-08-17 20:56:34.000000', NULL, 1),
(4007767, 572005, 45475, '<td valign="top">Gorgeous. No critique possible, only praise.</td>', 'Gorgeous. No critique possible, only praise.', '2007-08-17 20:56:38.000000', NULL, 1),
(4007768, 569859, 45475, '<td valign="top">Wonderful light!</td>', 'Wonderful light!', '2007-08-17 20:56:56.000000', NULL, 1),
(4007769, 571954, 45475, '<td valign="top">Strange colour palette, but I love the sky.</td>', 'Strange colour palette, but I love the sky.', '2007-08-17 20:57:27.000000', NULL, 1),
(4007770, 571117, 45475, '<td valign="top">Colours look great, nice work.</td>', 'Colours look great, nice work.', '2007-08-17 20:57:50.000000', NULL, 1),
(4007771, 568343, 45475, '<td valign="top">Glorious!</td>', 'Glorious!', '2007-08-17 20:58:07.000000', NULL, 1),
(4007775, 569119, 45475, '<td valign="top">Great timing. Rain on it''s way and a rainbow to boot!</td>', 'Great timing. Rain on it''s way and a rainbow to boot!', '2007-08-17 20:59:08.000000', NULL, 1),
(4007776, 568253, 81852, '<td valign="top">Why black and white? I would love to see the blue sky against the gold of the hillside.  I like the composition though. Nice.</td>', 'Why black and white? I would love to see the blue sky against the gold of the hillside.  I like the composition though. Nice.', '2007-08-17 20:59:21.000000', NULL, 1),
(4007777, 572001, 45475, '<td valign="top">Good light and colour, nicely composed.</td>', 'Good light and colour, nicely composed.', '2007-08-17 20:59:44.000000', NULL, 1),
(4007778, 571951, 81852, '<td valign="top">Interesting contrast between the power lines and the prairie grass.</td>', 'Interesting contrast between the power lines and the prairie grass.', '2007-08-17 21:01:34.000000', NULL, 1),
(4007782, 570717, 35802, '<td valign="top">Alot of noise</td>', 'Alot of noise', '2007-08-17 21:02:19.000000', NULL, 1),
(4007784, 570823, 81852, '<td valign="top">The shadows are so dark against the light areas.</td>', 'The shadows are so dark against the light areas.', '2007-08-17 21:03:18.000000', NULL, 1),
(4007787, 569996, 81852, '<td valign="top">That''s funny right there. Don''t care who ya are.</td>', 'That''s funny right there. Don''t care who ya are.', '2007-08-17 21:04:13.000000', NULL, 1),
(4007788, 570085, 45475, '<td valign="top">Oh dear, went a little crazy on the sharpening? Could be just my eyes though (sometimes not very reliable). What a grand scene this is however. Would love to see the original size. I bet it''s breathtaking. There''s a lot to love about this image - the sky, the cows, the mountains... so you''re getting an 8 from me! :)</td>', 'Oh dear, went a little crazy on the sharpening? Could be just my eyes though (sometimes not very reliable). What a grand scene this is however. Would love to see the original size. I bet it''s breathtaking. There''s a lot to love about this image - the sky, the cows, the mountains... so you''re getting an 8 from me! :)', '2007-08-17 21:04:20.000000', NULL, 1),
(4007797, 571827, 45475, '<td valign="top">Looks a little over exposed and hazy. Spectacular view though!</td>', 'Looks a little over exposed and hazy. Spectacular view though!', '2007-08-17 21:07:04.000000', NULL, 1),
(4007799, 571774, 81852, '<td valign="top">Oversaturated and blurry.</td>', 'Oversaturated and blurry.', '2007-08-17 21:07:31.000000', NULL, 1),
(4007801, 571477, 81852, '<td valign="top">I love this. So pretty.</td>', 'I love this. So pretty.', '2007-08-17 21:08:38.000000', NULL, 1),
(4007805, 570974, 81852, '<td valign="top">I keep looking for the funnel cloud.  Nice color.</td>', 'I keep looking for the funnel cloud.  Nice color.', '2007-08-17 21:09:47.000000', NULL, 1),
(4007812, 571678, 81852, '<td valign="top">Ok, this is the best one I''ve seen yet in this challenge. Wow!</td>', 'Ok, this is the best one I''ve seen yet in this challenge. Wow!', '2007-08-17 21:12:34.000000', NULL, 1),
(4007816, 568253, 45475, '<td valign="top">Starving for some highlights I think. Too grey. Love the scene though :)</td>', 'Starving for some highlights I think. Too grey. Love the scene though :)', '2007-08-17 21:13:45.000000', NULL, 1),
(4007818, 570717, 81852, '<td valign="top">Very nice.</td>', 'Very nice.', '2007-08-17 21:13:50.000000', NULL, 1),
(4007819, 570887, 81852, '<td valign="top">That is rural all right. Looks like the parades we have in my town.</td>', 'That is rural all right. Looks like the parades we have in my town.', '2007-08-17 21:16:25.000000', NULL, 1),
(4007829, 571380, 45475, '<td valign="top">Hmmm... not too keen on the colour choices for this. Marvellous scene though.</td>', 'Hmmm... not too keen on the colour choices for this. Marvellous scene though.', '2007-08-17 21:20:07.000000', NULL, 1),
(4007834, 570427, 81852, '<td valign="top">That would be cool to see!  Really like this. The colors are great.</td>', 'That would be cool to see!  Really like this. The colors are great.', '2007-08-17 21:22:13.000000', NULL, 1),
(4007837, 570993, 82503, '<td valign="top">Awesome shot! Love the colors and the clouds.</td>', 'Awesome shot! Love the colors and the clouds.', '2007-08-17 21:23:19.000000', NULL, 1),
(4007838, 571992, 81852, '<td valign="top">The corn is just lost into the rest of the landscape.</td>', 'The corn is just lost into the rest of the landscape.', '2007-08-17 21:23:24.000000', NULL, 1),
(4007841, 569261, 41581, '<td valign="top">Love the picture.  I just wish it were more of a rural landscape.</td>', 'Love the picture.  I just wish it were more of a rural landscape.', '2007-08-17 21:24:21.000000', NULL, 1),
(4007842, 571042, 45475, '<td valign="top">Wowowowow.... too bad it''s so tiny. Problems with your editing software? Check the Tricks and Tips forums here for threads on resizing for web issues. Anyway, can''t help thinking it''s one of the better shots in this challenge all the same. 8 :)</td>', 'Wowowowow.... too bad it''s so tiny. Problems with your editing software? Check the Tricks and Tips forums here for threads on resizing for web issues. Anyway, can''t help thinking it''s one of the better shots in this challenge all the same. 8 :)', '2007-08-17 21:24:50.000000', NULL, 1),
(4007846, 571311, 81852, '<td valign="top">Image quality is not good.  I can see the pixels.  Would be really nice otherwise.</td>', 'Image quality is not good.  I can see the pixels.  Would be really nice otherwise.', '2007-08-17 21:26:20.000000', NULL, 1),
(4007847, 571292, 45475, '<td valign="top">Oh, you had to have known that this would tug the heartstrings for many. Excellent work and perfect title :)</td>', 'Oh, you had to have known that this would tug the heartstrings for many. Excellent work and perfect title :)', '2007-08-17 21:26:41.000000', NULL, 1),
(4007849, 571830, 81852, '<td valign="top">Oversaturated.</td>', 'Oversaturated.', '2007-08-17 21:27:55.000000', NULL, 1),
(4007851, 569876, 11653, '<td valign="top">does not meet challenge</td>', 'does not meet challenge', '2007-08-17 21:29:29.000000', NULL, 1),
(4007853, 570191, 11653, '<td valign="top">lacks clarity</td>', 'lacks clarity', '2007-08-17 21:30:06.000000', NULL, 1),
(4007856, 570451, 81852, '<td valign="top">Nice crop! This is cool!</td>', 'Nice crop! This is cool!', '2007-08-17 21:32:00.000000', NULL, 1),
(4007860, 570097, 81852, '<td valign="top">This would be nice if the lilies and the little girl were in focus.</td>', 'This would be nice if the lilies and the little girl were in focus.', '2007-08-17 21:33:13.000000', NULL, 1),
(4007861, 569891, 81852, '<td valign="top">Love it!</td>', 'Love it!', '2007-08-17 21:33:31.000000', NULL, 1),
(4007863, 569859, 82890, '<td valign="top">Great clouds</td>', 'Great clouds', '2007-08-17 21:34:08.000000', NULL, 1),
(4007865, 571777, 41581, '<td valign="top">Points for color scheme.  Horizontal balance is a bit off.  I have real difficulty with this as a Rural Landscape.</td>', 'Points for color scheme.  Horizontal balance is a bit off.  I have real difficulty with this as a Rural Landscape.', '2007-08-17 21:34:33.000000', NULL, 1),
(4007866, 571066, 82890, '<td valign="top">Colors or filtering makes it look unnatural.</td>', 'Colors or filtering makes it look unnatural.', '2007-08-17 21:34:49.000000', NULL, 1),
(4007868, 571938, 81852, '<td valign="top">Good one for Jay Leno.  Very funny.</td>', 'Good one for Jay Leno.  Very funny.', '2007-08-17 21:34:56.000000', NULL, 1),
(4007870, 571148, 41581, '<td valign="top">Wow!  Electrifying color!</td>', 'Wow!  Electrifying color!', '2007-08-17 21:35:25.000000', NULL, 1),
(4007871, 571086, 82890, '<td valign="top">The slight delay in shutter time adds the perfect effect</td>', 'The slight delay in shutter time adds the perfect effect', '2007-08-17 21:35:40.000000', NULL, 1),
(4007873, 571311, 41581, '<td valign="top">Train in background takes too much away from the barn.  Not a fan of the grainy look.</td>', 'Train in background takes too much away from the barn.  Not a fan of the grainy look.', '2007-08-17 21:36:04.000000', NULL, 1),
(4007874, 570969, 82890, '<td valign="top">Wire cutting across is very distracting</td>', 'Wire cutting across is very distracting', '2007-08-17 21:36:14.000000', NULL, 1),
(4007875, 571425, 81852, '<td valign="top">This is nice.</td>', 'This is nice.', '2007-08-17 21:36:26.000000', NULL, 1),
(4007876, 571042, 41581, '<td valign="top">I wished I could see this one bigger.  Great leading lines and rich color.</td>', 'I wished I could see this one bigger.  Great leading lines and rich color.', '2007-08-17 21:36:51.000000', NULL, 1),
(4007878, 568278, 82890, '<td valign="top">the blues are a bit too accented, in the mountains specifically</td>', 'the blues are a bit too accented, in the mountains specifically', '2007-08-17 21:37:16.000000', NULL, 1),
(4007883, 569798, 81852, '<td valign="top">Great color!</td>', 'Great color!', '2007-08-17 21:38:57.000000', NULL, 1),
(4007885, 569275, 41581, '<td valign="top">Slight horizontal slope down to the right is distracting.  Like the leading lines in the rocks.  Could you have repositioned the picture to exclude the yellow grass in the right lower corner?  Perhaps shift the photo to the left?</td>', 'Slight horizontal slope down to the right is distracting.  Like the leading lines in the rocks.  Could you have repositioned the picture to exclude the yellow grass in the right lower corner?  Perhaps shift the photo to the left?', '2007-08-17 21:39:10.000000', NULL, 1),
(4007886, 569391, 82890, '<td valign="top">Great composition and color</td>', 'Great composition and color', '2007-08-17 21:39:14.000000', NULL, 1),
(4007888, 571397, 82890, '<td valign="top">Great capture!</td>', 'Great capture!', '2007-08-17 21:39:54.000000', NULL, 1),
(4007889, 570243, 41581, '<td valign="top">Neat shot!  I like how the blues come out in the farm.</td>', 'Neat shot!  I like how the blues come out in the farm.', '2007-08-17 21:39:55.000000', NULL, 1),
(4007894, 569876, 81852, '<td valign="top">Ok.</td>', 'Ok.', '2007-08-17 21:43:49.000000', NULL, 1),
(4007897, 569194, 81852, '<td valign="top">Why so dark?</td>', 'Why so dark?', '2007-08-17 21:44:12.000000', NULL, 1),
(4007899, 570035, 81852, '<td valign="top">Not where I would want to be in that storm! But cool photo.</td>', 'Not where I would want to be in that storm! But cool photo.', '2007-08-17 21:45:18.000000', NULL, 1),
(4007901, 571258, 41581, '<td valign="top">Soothing photo.  I like the branches in the foreground, but wish there was a little more light.</td>', 'Soothing photo.  I like the branches in the foreground, but wish there was a little more light.', '2007-08-17 21:46:53.000000', NULL, 1),
(4007903, 571117, 41581, '<td valign="top">Neat red on green!</td>', 'Neat red on green!', '2007-08-17 21:47:43.000000', NULL, 1),
(4007904, 568390, 81852, '<td valign="top">Not sure what happened to this one.</td>', 'Not sure what happened to this one.', '2007-08-17 21:48:31.000000', NULL, 1),
(4007906, 568343, 41581, '<td valign="top">Great timing!</td>', 'Great timing!', '2007-08-17 21:49:48.000000', NULL, 1),
(4007912, 568390, 41581, '<td valign="top">Crossroad scene has potential, but this has too much pavement in the foreground.  The lighting isn''t strong enough to do the red color justice.</td>', 'Crossroad scene has potential, but this has too much pavement in the foreground.  The lighting isn''t strong enough to do the red color justice.', '2007-08-17 21:51:28.000000', NULL, 1),
(4007926, 571939, 41581, '<td valign="top">Love this!</td>', 'Love this!', '2007-08-17 21:56:13.000000', NULL, 1),
(4007928, 571827, 2553, '<td valign="top">Hmmm...interesting scene, and it has definite possibilities, but something seems just a little "off".  I''d just like to see it "pop" a bit more I think.</td>', 'Hmmm...interesting scene, and it has definite possibilities, but something seems just a little "off".  I''d just like to see it "pop" a bit more I think.', '2007-08-17 21:57:04.000000', NULL, 1),
(4007930, 570155, 41581, '<td valign="top">I would rotate this to level the horizon.</td>', 'I would rotate this to level the horizon.', '2007-08-17 21:57:23.000000', NULL, 1),
(4007946, 570883, 2553, '<td valign="top">I had to look at this for a bit before I could really make out what was going on.  I like the concept, but find that the preponderence of darkness doesn''t really seem to do this justice.  Also, the odd conflicting light sources - warm light on the left and cool light on the right - feels kind of odd to me.  A longer exposure on the man and the horizon might have been interesting.</td>', 'I had to look at this for a bit before I could really make out what was going on.  I like the concept, but find that the preponderence of darkness doesn''t really seem to do this justice.  Also, the odd conflicting light sources - warm light on the left and cool light on the right - feels kind of odd to me.  A longer exposure on the man and the horizon might have been interesting.', '2007-08-17 22:00:21.000000', NULL, 1),
(4007949, 571825, 41581, '<td valign="top">Soothing...</td>', 'Soothing...', '2007-08-17 22:02:16.000000', NULL, 1),
(4007954, 569920, 2553, '<td valign="top">I''m not really sure what to say about this.  The left side is so strong, compositionally with the great leading lines, but then your eye wanders to the right side you kind of get sidetracked by the horse, and then the little tree that leans off the edge of the frame. I''m not sure what would have made this "flow" better but the composition feels a bit off for me.</td>', 'I''m not really sure what to say about this.  The left side is so strong, compositionally with the great leading lines, but then your eye wanders to the right side you kind of get sidetracked by the horse, and then the little tree that leans off the edge of the frame. I''m not sure what would have made this "flow" better but the composition feels a bit off for me.', '2007-08-17 22:05:07.000000', NULL, 1),
(4007957, 571397, 2553, '<td valign="top">Beautiful color and saturation, and a cute shot for sure, but the perspective on the horse makes it feel odd to me.</td>', 'Beautiful color and saturation, and a cute shot for sure, but the perspective on the horse makes it feel odd to me.', '2007-08-17 22:06:39.000000', NULL, 1),
(4007958, 571905, 41581, '<td valign="top">This is a hair off level, which distracts since the composition has so many edges.  However, it is a lovely composition.  Center the rug and level against the water line.</td>', 'This is a hair off level, which distracts since the composition has so many edges.  However, it is a lovely composition.  Center the rug and level against the water line.', '2007-08-17 22:07:26.000000', NULL, 1),
(4007961, 568549, 41581, '<td valign="top">Composition and balance are good.  A little more sharpness in the foreground would make the photo pop.</td>', 'Composition and balance are good.  A little more sharpness in the foreground would make the photo pop.', '2007-08-17 22:08:20.000000', NULL, 1),
(4007965, 571136, 2553, '<td valign="top">Wow, the sky on this image is just amazing!  I really like this, but the trees bug me - they just seem intrusive in the image.  Would love to have seen it with just the buildings and the sky.</td>', 'Wow, the sky on this image is just amazing!  I really like this, but the trees bug me - they just seem intrusive in the image.  Would love to have seen it with just the buildings and the sky.', '2007-08-17 22:08:32.000000', NULL, 1),
(4007968, 571922, 41581, '<td valign="top">Rich red!</td>', 'Rich red!', '2007-08-17 22:09:31.000000', NULL, 1),
(4007971, 571675, 41581, '<td valign="top">Nice subject.  Love the splash of purple.  Try cropping the right side.  The sky on the upper right throws the balance off.</td>', 'Nice subject.  Love the splash of purple.  Try cropping the right side.  The sky on the upper right throws the balance off.', '2007-08-17 22:11:17.000000', NULL, 1),
(4007972, 570427, 2553, '<td valign="top">Cool!  Wish someone would do that in MY backyard!  Really like the different elements that make up this shot.  It''s interesting to look at.</td>', 'Cool!  Wish someone would do that in MY backyard!  Really like the different elements that make up this shot.  It''s interesting to look at.', '2007-08-17 22:11:31.000000', NULL, 1),
(4007976, 571696, 2553, '<td valign="top">Honestly, even with the title, this image doesn''t really tell me much.  My first thought was that it was kind of eerie feeling.</td>', 'Honestly, even with the title, this image doesn''t really tell me much.  My first thought was that it was kind of eerie feeling.', '2007-08-17 22:12:49.000000', NULL, 1),
(4007979, 569421, 2553, '<td valign="top">Though I really love black and white, this image doesn''t have enough tonal range for my taste.  Other than the leading lines, I don''t find it very interesting - I just feel like it doesn''t really tell me anything.</td>', 'Though I really love black and white, this image doesn''t have enough tonal range for my taste.  Other than the leading lines, I don''t find it very interesting - I just feel like it doesn''t really tell me anything.', '2007-08-17 22:14:50.000000', NULL, 1),
(4007981, 571951, 41581, '<td valign="top">Rotate to level.</td>', 'Rotate to level.', '2007-08-17 22:15:27.000000', NULL, 1),
(4007983, 570104, 2553, '<td valign="top">I feel like this "could" have been a really cool image, but the sky just completely blows it for me.  That color is just not at all natural looking, and even as "artistic expression", it feels very harsh.</td>', 'I feel like this "could" have been a really cool image, but the sky just completely blows it for me.  That color is just not at all natural looking, and even as "artistic expression", it feels very harsh.', '2007-08-17 22:16:10.000000', NULL, 1),
(4007988, 570318, 2553, '<td valign="top">Oh yeah, very cool image.  The only thing that would have helped dramatically would have been an awesome sky.  Gorgeous patterns though.</td>', 'Oh yeah, very cool image.  The only thing that would have helped dramatically would have been an awesome sky.  Gorgeous patterns though.', '2007-08-17 22:17:00.000000', NULL, 1),
(4007991, 570870, 2553, '<td valign="top">I totally and completely love this image.  Very nice, however you did it.</td>', 'I totally and completely love this image.  Very nice, however you did it.', '2007-08-17 22:18:08.000000', NULL, 1),
(4007992, 570969, 41581, '<td valign="top">I like the old tone to this photo.  Well chosen leading lines with the plowed side and the pasture side.  The wire in the foreground is too distracting for my tastes though.</td>', 'I like the old tone to this photo.  Well chosen leading lines with the plowed side and the pasture side.  The wire in the foreground is too distracting for my tastes though.', '2007-08-17 22:18:18.000000', NULL, 1),
(4007994, 570427, 41581, '<td valign="top">Right place, right time!</td>', 'Right place, right time!', '2007-08-17 22:18:54.000000', NULL, 1),
(4007996, 572001, 2553, '<td valign="top">Interesting, nice tonal range and you managed to capture the sky nicely.</td>', 'Interesting, nice tonal range and you managed to capture the sky nicely.', '2007-08-17 22:19:18.000000', NULL, 1),
(4007998, 571042, 2553, '<td valign="top">Gorgeous sky, and a nice image, but so small, I think this would look nice larger.</td>', 'Gorgeous sky, and a nice image, but so small, I think this would look nice larger.', '2007-08-17 22:20:05.000000', NULL, 1),
(4008000, 569883, 2553, '<td valign="top">Wish I could make out if all that red was dirt or flowers.  Cool image though.</td>', 'Wish I could make out if all that red was dirt or flowers.  Cool image though.', '2007-08-17 22:20:50.000000', NULL, 1),
(4008002, 568951, 2553, '<td valign="top">In my opinion this just does not fit into the rural landscape category no matter how you look at it.</td>', 'In my opinion this just does not fit into the rural landscape category no matter how you look at it.', '2007-08-17 22:21:35.000000', NULL, 1),
(4008006, 570327, 2553, '<td valign="top">The very light area at the top right just commands way too much attention.  So much so that I have to really focus on the rabbit to see him well.  Too bad you couldn''t have gotten more light on the little guy.</td>', 'The very light area at the top right just commands way too much attention.  So much so that I have to really focus on the rabbit to see him well.  Too bad you couldn''t have gotten more light on the little guy.', '2007-08-17 22:23:01.000000', NULL, 1),
(4008007, 570848, 2553, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2007-08-17 22:23:18.000000', NULL, 1),
(4008015, 571674, 41581, '<td valign="top">I like the monochromatic approach.  I would level this.</td>', 'I like the monochromatic approach.  I would level this.', '2007-08-17 22:25:01.000000', NULL, 1),
(4008017, 570974, 2553, '<td valign="top">Whoa!  I''d just LOVE to see some advanced editing on this image.  It is just so compelling, and the buildings and foreground are just begging to be brightened up.</td>', 'Whoa!  I''d just LOVE to see some advanced editing on this image.  It is just so compelling, and the buildings and foreground are just begging to be brightened up.', '2007-08-17 22:25:23.000000', NULL, 1),
(4008022, 571250, 41581, '<td valign="top">Interesting.  It draws you in.</td>', 'Interesting.  It draws you in.', '2007-08-17 22:26:31.000000', NULL, 1),
(4008023, 570717, 74979, '<td valign="top">sad old image...amazing they don''t fall down!</td>', 'sad old image...amazing they don''t fall down!', '2007-08-17 22:27:26.000000', NULL, 1),
(4008025, 571232, 2553, '<td valign="top">Can''t put my finger on it, but something looks odd about this image.  Sun rays are pretty cool though.</td>', 'Can''t put my finger on it, but something looks odd about this image.  Sun rays are pretty cool though.', '2007-08-17 22:27:38.000000', NULL, 1),
(4008032, 570821, 2553, '<td valign="top">A very interesting image.  Would have liked to have seen it "pop" just a bit more.  The title really confuses me though...</td>', 'A very interesting image.  Would have liked to have seen it "pop" just a bit more.  The title really confuses me though...', '2007-08-17 22:29:42.000000', NULL, 1),
(4008044, 568315, 2553, '<td valign="top">Absolutely took my breath away the moment I saw it.  The first 10 I''ve given out so far too.  This is just lovely.</td>', 'Absolutely took my breath away the moment I saw it.  The first 10 I''ve given out so far too.  This is just lovely.', '2007-08-17 22:32:42.000000', NULL, 1),
(4008050, 571678, 2553, '<td valign="top">Oh my.  10. Nothing else to say.</td>', 'Oh my.  10. Nothing else to say.', '2007-08-17 22:34:04.000000', NULL, 1),
(4008059, 570451, 2553, '<td valign="top">Well, there you go.  You start thinking that you just aren''t going to see anything "unexpected", and then you see it.  Interesting, unusual, compelling.</td>', 'Well, there you go.  You start thinking that you just aren''t going to see anything "unexpected", and then you see it.  Interesting, unusual, compelling.', '2007-08-17 22:35:23.000000', NULL, 1),
(4008061, 569261, 38930, '<td valign="top">perfect 10</td>', 'perfect 10', '2007-08-17 22:36:23.000000', NULL, 1),
(4008062, 569879, 2553, '<td valign="top">L-O-V-E the perspective!  It''s so surprising and refreshing to see a different viewpoint.</td>', 'L-O-V-E the perspective!  It''s so surprising and refreshing to see a different viewpoint.', '2007-08-17 22:36:46.000000', NULL, 1),
(4008065, 569891, 2553, '<td valign="top">OK, whoa...I just commented on appreciating a different perspective, but this really makes me feel creepy and disoriented.  Interesting though..,</td>', 'OK, whoa...I just commented on appreciating a different perspective, but this really makes me feel creepy and disoriented.  Interesting though..,', '2007-08-17 22:37:52.000000', NULL, 1),
(4008069, 570575, 2553, '<td valign="top">This really makes me miss the Smokies, it looks so much like that.</td>', 'This really makes me miss the Smokies, it looks so much like that.', '2007-08-17 22:39:57.000000', NULL, 1),
(4008072, 569261, 2553, '<td valign="top">Wow, what a shot!  I''d be shocked not to see this on the front page.</td>', 'Wow, what a shot!  I''d be shocked not to see this on the front page.', '2007-08-17 22:41:34.000000', NULL, 1),
(4008073, 569876, 2553, '<td valign="top">How ridiculous.</td>', 'How ridiculous.', '2007-08-17 22:43:00.000000', NULL, 1),
(4008074, 570825, 38930, '<td valign="top">I bet this would be AWESOME in HDR!</td>', 'I bet this would be AWESOME in HDR!', '2007-08-17 22:43:08.000000', NULL, 1),
(4008075, 568922, 38930, '<td valign="top">great find!</td>', 'great find!', '2007-08-17 22:43:19.000000', NULL, 1),
(4008078, 572003, 38930, '<td valign="top">nice title :)</td>', 'nice title :)', '2007-08-17 22:43:54.000000', NULL, 1),
(4008080, 569111, 38930, '<td valign="top">a-w-e-s-o-m-e!!  10 &amp; Fav''s</td>', 'a-w-e-s-o-m-e!!  10 & Fav''s', '2007-08-17 22:44:50.000000', NULL, 1),
(4008081, 569891, 38930, '<td valign="top">sweet</td>', 'sweet', '2007-08-17 22:45:20.000000', NULL, 1),
(4008082, 571876, 38930, '<td valign="top">it''s what''s for dinner</td>', 'it''s what''s for dinner', '2007-08-17 22:45:49.000000', NULL, 1),
(4008085, 570974, 38930, '<td valign="top">are those hippos?</td>', 'are those hippos?', '2007-08-17 22:47:21.000000', NULL, 1),
(4008086, 571425, 41581, '<td valign="top">Great subject!</td>', 'Great subject!', '2007-08-17 22:47:36.000000', NULL, 1),
(4008096, 570993, 2553, '<td valign="top">This looks very, very strange!</td>', 'This looks very, very strange!', '2007-08-17 22:51:59.000000', NULL, 1),
(4008097, 571380, 33379, '<td valign="top">I love this sky!</td>', 'I love this sky!', '2007-08-17 22:52:36.000000', NULL, 1),
(4008131, 572005, 41581, '<td valign="top">Well balanced!</td>', 'Well balanced!', '2007-08-17 23:09:05.000000', NULL, 1),
(4008205, 570191, 76430, '<td valign="top">Too small and the portrait mode doesn''t allow us to see much of the scene</td>', 'Too small and the portrait mode doesn''t allow us to see much of the scene', '2007-08-17 23:55:42.000000', NULL, 1),
(4008206, 570969, 76430, '<td valign="top">The horizontal fencing near the camera really distracts.  I''d recommend setting the camera ON that wire.  Good sepia image otherwise.</td>', 'The horizontal fencing near the camera really distracts.  I''d recommend setting the camera ON that wire.  Good sepia image otherwise.', '2007-08-17 23:55:51.000000', NULL, 1),
(4008207, 571386, 76430, '<td valign="top">Too small, not very sharp, and not a landscape</td>', 'Too small, not very sharp, and not a landscape', '2007-08-17 23:56:23.000000', NULL, 1),
(4008209, 571442, 76430, '<td valign="top">Landscape?  Maybe if we were looking at the stuff on the shelf through the window and could see a landscape.</td>', 'Landscape?  Maybe if we were looking at the stuff on the shelf through the window and could see a landscape.', '2007-08-17 23:56:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4008216, 570058, 82077, '<td valign="top">Nice shot. Really captures the feeling of being in the country.</td>', 'Nice shot. Really captures the feeling of being in the country.', '2007-08-18 00:02:02.000000', NULL, 1),
