(4009207, 570328, 82890, '<td valign="top">That absolutely feels like Britain. Cheers!</td>', 'That absolutely feels like Britain. Cheers!', '2007-08-18 13:53:42.000000', NULL, 1),
(4009208, 571731, 82890, '<td valign="top">Oh the life of a horse... Brilliant coloring, especially the sky.</td>', 'Oh the life of a horse... Brilliant coloring, especially the sky.', '2007-08-18 13:54:01.000000', NULL, 1),
(4009210, 572003, 82890, '<td valign="top">If the sign were faded out as much as the rest of the picture this would be perfect.</td>', 'If the sign were faded out as much as the rest of the picture this would be perfect.', '2007-08-18 13:54:48.000000', NULL, 1),
(4009213, 570035, 82890, '<td valign="top">Great capture of the lightning there. Too bad there''s a car in the middle of the picture...</td>', 'Great capture of the lightning there. Too bad there''s a car in the middle of the picture...', '2007-08-18 13:55:47.000000', NULL, 1),
(4009215, 572005, 82890, '<td valign="top">Love the cloud formations.</td>', 'Love the cloud formations.', '2007-08-18 13:56:07.000000', NULL, 1),
(4009217, 568960, 82890, '<td valign="top">Powerful coloring...</td>', 'Powerful coloring...', '2007-08-18 13:56:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4009220, 570451, 82890, '<td valign="top">Clever</td>', 'Clever', '2007-08-18 13:57:12.000000', NULL, 1),
(4009222, 571896, 41675, '<td valign="top">Looks like it was a bit of a hazy day. Nice composition. I like the fields in the background. I wonder what this would look like if it was cropped a little bit more in from the bottom? for me, the rock wall is acting like a bit of a visual barrier.</td>', 'Looks like it was a bit of a hazy day. Nice composition. I like the fields in the background. I wonder what this would look like if it was cropped a little bit more in from the bottom? for me, the rock wall is acting like a bit of a visual barrier.', '2007-08-18 13:57:32.000000', NULL, 1),
(4009224, 571799, 41675, '<td valign="top">I wish there was a bit more saturation. I like the view though - looks cool.</td>', 'I wish there was a bit more saturation. I like the view though - looks cool.', '2007-08-18 13:58:07.000000', NULL, 1),
(4009227, 570812, 41675, '<td valign="top">Your title made me smile. Having the man in there keeps your photo from being boring. I like the reflectins.</td>', 'Your title made me smile. Having the man in there keeps your photo from being boring. I like the reflectins.', '2007-08-18 13:58:53.000000', NULL, 1),
(4009229, 568549, 41675, '<td valign="top">Nice farming image. I like the colors.</td>', 'Nice farming image. I like the colors.', '2007-08-18 13:59:25.000000', NULL, 1),
(4009231, 570788, 41675, '<td valign="top">Very pretty vista. I like the large expansive sky. Looks almost idyllic.</td>', 'Very pretty vista. I like the large expansive sky. Looks almost idyllic.', '2007-08-18 14:00:20.000000', NULL, 1),
(4009233, 571944, 41675, '<td valign="top">With a bit more color saturation and contrast I would have scored this higher. Looks like a pretty spot.</td>', 'With a bit more color saturation and contrast I would have scored this higher. Looks like a pretty spot.', '2007-08-18 14:01:15.000000', NULL, 1),
(4009235, 570970, 82890, '<td valign="top">I''ve so been to this field! I think I have almost the same shot too!</td>', 'I''ve so been to this field! I think I have almost the same shot too!', '2007-08-18 14:01:46.000000', NULL, 1),
(4009236, 571056, 41675, '<td valign="top">Your title and photo make me smile. It makes me wonder where he''s headed.</td>', 'Your title and photo make me smile. It makes me wonder where he''s headed.', '2007-08-18 14:02:00.000000', NULL, 1),
(4009240, 572005, 41675, '<td valign="top">Unique...and a beautiful photograph. Wonderful sky, good composition. I like the field of flowers in the foreground too. Good luck in the challenge.</td>', 'Unique...and a beautiful photograph. Wonderful sky, good composition. I like the field of flowers in the foreground too. Good luck in the challenge.', '2007-08-18 14:02:35.000000', NULL, 1),
(4009243, 569222, 41675, '<td valign="top">The lighting is a little harsh for me, but I like the foreground leaf on the right covering the tree reflection. That''s my favorite part of your photo.</td>', 'The lighting is a little harsh for me, but I like the foreground leaf on the right covering the tree reflection. That''s my favorite part of your photo.', '2007-08-18 14:03:52.000000', NULL, 1),
(4009244, 569996, 41675, '<td valign="top">Lol - well, that looks like country living alrright. Seems like a quick snapshot. Perhaps if the baby were cropped out and it was just the man with his beer, it might be more effective.</td>', 'Lol - well, that looks like country living alrright. Seems like a quick snapshot. Perhaps if the baby were cropped out and it was just the man with his beer, it might be more effective.', '2007-08-18 14:05:03.000000', NULL, 1),
(4009246, 572008, 41675, '<td valign="top">Seems a little overly processed to me. Especially in the middle and around the bench. I does look like an interesting building though.</td>', 'Seems a little overly processed to me. Especially in the middle and around the bench. I does look like an interesting building though.', '2007-08-18 14:06:00.000000', NULL, 1),
(4009249, 568189, 41675, '<td valign="top">Country living and Kentucky fried - you just made me hungry. Lol. I wonder how this would look if you cropped in closer to the rooster. He has some bbeautiful markings.</td>', 'Country living and Kentucky fried - you just made me hungry. Lol. I wonder how this would look if you cropped in closer to the rooster. He has some bbeautiful markings.', '2007-08-18 14:07:05.000000', NULL, 1),
(4009252, 568197, 41675, '<td valign="top">I like the sofftness of your image. Good lighting as well. It gives me a sense of peace and tranquility. Good luck in the challenge.</td>', 'I like the sofftness of your image. Good lighting as well. It gives me a sense of peace and tranquility. Good luck in the challenge.', '2007-08-18 14:07:49.000000', NULL, 1),
(4009254, 571241, 41675, '<td valign="top">It took me a minute or two to figure out the title. I''m guessing thats for a wedding? It looks very pretty. The white gazebo and chairs really stand out against the landscape.</td>', 'It took me a minute or two to figure out the title. I''m guessing thats for a wedding? It looks very pretty. The white gazebo and chairs really stand out against the landscape.', '2007-08-18 14:09:24.000000', NULL, 1),
(4009256, 570117, 41675, '<td valign="top">I wish there was a bit more contrast to enhance your image. I like the fog though. I wonder how this would look in black &amp; white?</td>', 'I wish there was a bit more contrast to enhance your image. I like the fog though. I wonder how this would look in black & white?', '2007-08-18 14:10:28.000000', NULL, 1),
(4009259, 569892, 41675, '<td valign="top">Nice sunset, but other than that area of your image, it doesn''t hold my image as long as other photos in this challenge. I do like the fact you can see the light rays though.</td>', 'Nice sunset, but other than that area of your image, it doesn''t hold my image as long as other photos in this challenge. I do like the fact you can see the light rays though.', '2007-08-18 14:11:36.000000', NULL, 1),
(4009260, 570058, 41675, '<td valign="top">For me, a bit more color saturation would enhance your photo. The colors appear a little...flat to me. I like the composition though.</td>', 'For me, a bit more color saturation would enhance your photo. The colors appear a little...flat to me. I like the composition though.', '2007-08-18 14:12:10.000000', NULL, 1),
(4009263, 571050, 41675, '<td valign="top">Your foreground seems a little dark, but I like the sky.</td>', 'Your foreground seems a little dark, but I like the sky.', '2007-08-18 14:13:22.000000', NULL, 1),
(4009264, 569391, 41675, '<td valign="top">Nice pasture photo. I like the horse in the front. Colors seem a little muted, but still a nice image.</td>', 'Nice pasture photo. I like the horse in the front. Colors seem a little muted, but still a nice image.', '2007-08-18 14:14:05.000000', NULL, 1),
(4009269, 570752, 41675, '<td valign="top">For me, your photo is very busy with all the cross lines of the fence and the distraction of the half of tree. I do like the way the light hits the horse''s nose and the trees in the background though.</td>', 'For me, your photo is very busy with all the cross lines of the fence and the distraction of the half of tree. I do like the way the light hits the horse''s nose and the trees in the background though.', '2007-08-18 14:15:32.000000', NULL, 1),
(4009272, 570026, 41675, '<td valign="top">Interesting. In a way, its a nice change of pace from all the "traditional" landscapes. Not all that exciting for me personally to look at wood with rusted nails, but I do like the texture.</td>', 'Interesting. In a way, its a nice change of pace from all the "traditional" landscapes. Not all that exciting for me personally to look at wood with rusted nails, but I do like the texture.', '2007-08-18 14:16:18.000000', NULL, 1),
(4009282, 571380, 56441, '<td valign="top">Love the colors!</td>', 'Love the colors!', '2007-08-18 14:20:49.000000', NULL, 1),
(4009283, 571668, 56441, '<td valign="top">Simple yet stunning</td>', 'Simple yet stunning', '2007-08-18 14:21:31.000000', NULL, 1),
(4009386, 570807, 31885, '<td valign="top">Hey, I know that place! Nice leading lines and colouring.</td>', 'Hey, I know that place! Nice leading lines and colouring.', '2007-08-18 15:50:25.000000', NULL, 1),
(4009409, 571830, 62249, '<td valign="top">The saturation and oversharpening give this the look of a 1970s postcard. Don''t know if that''s what you intended but it''s kinda interesting.</td>', 'The saturation and oversharpening give this the look of a 1970s postcard. Don''t know if that''s what you intended but it''s kinda interesting.', '2007-08-18 16:13:17.000000', NULL, 1),
(4009411, 570870, 62249, '<td valign="top">Unusual but captivating. Good job.</td>', 'Unusual but captivating. Good job.', '2007-08-18 16:15:16.000000', NULL, 1),
(4009412, 571232, 62249, '<td valign="top">The extreme post-processing isn''t all that effective on this shot.</td>', 'The extreme post-processing isn''t all that effective on this shot.', '2007-08-18 16:19:17.000000', NULL, 1),
(4009444, 571924, 62249, '<td valign="top">Interesting subject. Maybe crop a little tighter on the sides.</td>', 'Interesting subject. Maybe crop a little tighter on the sides.', '2007-08-18 16:49:39.000000', NULL, 1),
(4009454, 569388, 62249, '<td valign="top">Has a peculiar color cast. I think tighter cropping would emphasize the viaduct better.</td>', 'Has a peculiar color cast. I think tighter cropping would emphasize the viaduct better.', '2007-08-18 16:54:36.000000', NULL, 1),
(4009456, 570829, 62249, '<td valign="top">Nice contrast between the gray/green color of the thistle (?) in the foreground and the gold of the grass in the background.</td>', 'Nice contrast between the gray/green color of the thistle (?) in the foreground and the gold of the grass in the background.', '2007-08-18 16:56:10.000000', NULL, 1),
(4009457, 571397, 62249, '<td valign="top">Like the tail action.</td>', 'Like the tail action.', '2007-08-18 16:57:01.000000', NULL, 1),
(4009458, 571880, 62249, '<td valign="top">Cute. Try a tighter crop and sharper focus. It''s a bit blurry and there''s too much gravel in the foreground.</td>', 'Cute. Try a tighter crop and sharper focus. It''s a bit blurry and there''s too much gravel in the foreground.', '2007-08-18 16:59:05.000000', NULL, 1),
(4009459, 568826, 62249, '<td valign="top">The texture and tonality of the roof are quite nice. Wish the midtones &amp; shadows had a little more detail &amp; contrast.</td>', 'The texture and tonality of the roof are quite nice. Wish the midtones & shadows had a little more detail & contrast.', '2007-08-18 17:00:10.000000', NULL, 1),
(4009462, 569485, 62249, '<td valign="top">The washtub is the most interesting part of this composition. It has subtle lighting and a good tonal range. Try cropping this shot differently to emphasize the tub more and de-emphasize (or omit entirely) the logs on the right side.</td>', 'The washtub is the most interesting part of this composition. It has subtle lighting and a good tonal range. Try cropping this shot differently to emphasize the tub more and de-emphasize (or omit entirely) the logs on the right side.', '2007-08-18 17:03:30.000000', NULL, 1),
(4009465, 571722, 62249, '<td valign="top">Highlights are a little blown out, but I love the composition.</td>', 'Highlights are a little blown out, but I love the composition.', '2007-08-18 17:05:43.000000', NULL, 1),
(4009477, 569876, 73601, '<td valign="top">again....no attempt.....no vote</td>', 'again....no attempt.....no vote', '2007-08-18 17:15:35.000000', NULL, 1),
(4009480, 568793, 62249, '<td valign="top">The thick, black bars top &amp; bottom are very distracting, but aside from thiat it''s a well composed shot.</td>', 'The thick, black bars top & bottom are very distracting, but aside from thiat it''s a well composed shot.', '2007-08-18 17:16:19.000000', NULL, 1),
(4009483, 570752, 62249, '<td valign="top">Not enough shadow detail on the horse.</td>', 'Not enough shadow detail on the horse.', '2007-08-18 17:17:21.000000', NULL, 1),
(4009501, 568278, 62249, '<td valign="top">I used to ski here in the winter. Good use of fireweed in the foreground.</td>', 'I used to ski here in the winter. Good use of fireweed in the foreground.', '2007-08-18 17:23:35.000000', NULL, 1),
(4009503, 569301, 62249, '<td valign="top">Good depth of field.</td>', 'Good depth of field.', '2007-08-18 17:24:19.000000', NULL, 1),
(4009518, 570764, 62249, '<td valign="top">Good shot. Tells a good dramatic story. Crop off a bit of the dark foreground at the bottom.</td>', 'Good shot. Tells a good dramatic story. Crop off a bit of the dark foreground at the bottom.', '2007-08-18 17:32:46.000000', NULL, 1),
(4009524, 569352, 62249, '<td valign="top">I like the emphasis on the one poppy. Too bad you couldn''t spot edit the specs &amp; crud in the sky, but I know you can''t do that under Basic rules.</td>', 'I like the emphasis on the one poppy. Too bad you couldn''t spot edit the specs & crud in the sky, but I know you can''t do that under Basic rules.', '2007-08-18 17:39:14.000000', NULL, 1),
(4009528, 570451, 62249, '<td valign="top">Clever cropping. Extra points for originality.</td>', 'Clever cropping. Extra points for originality.', '2007-08-18 17:43:05.000000', NULL, 1),
(4009560, 571908, 82937, '<td valign="top">I think I might like this better in color.</td>', 'I think I might like this better in color.', '2007-08-18 18:00:50.000000', NULL, 1),
(4009561, 571117, 82937, '<td valign="top">beautiful parking lot!</td>', 'beautiful parking lot!', '2007-08-18 18:01:20.000000', NULL, 1),
(4009562, 570870, 82937, '<td valign="top">nice abstract feeling.</td>', 'nice abstract feeling.', '2007-08-18 18:01:57.000000', NULL, 1),
(4009563, 568343, 62249, '<td valign="top">Love the golden light pouring over the trees and the good tonal range in this shot. Hate the border.</td>', 'Love the golden light pouring over the trees and the good tonal range in this shot. Hate the border.', '2007-08-18 18:02:22.000000', NULL, 1),
(4009564, 571915, 82937, '<td valign="top">Love how clear the haybail is, nice shot.</td>', 'Love how clear the haybail is, nice shot.', '2007-08-18 18:02:30.000000', NULL, 1),
(4009566, 571906, 82937, '<td valign="top">Wow, I can smell the fresh paint!</td>', 'Wow, I can smell the fresh paint!', '2007-08-18 18:03:01.000000', NULL, 1),
(4009568, 570970, 82937, '<td valign="top">Like the shot, but I think it could do better if it was cropped.</td>', 'Like the shot, but I think it could do better if it was cropped.', '2007-08-18 18:03:47.000000', NULL, 1),
(4009571, 571999, 82937, '<td valign="top">Great shot, you can feel the desolation, but the sun and mountains in the distance contradict.  I love it.</td>', 'Great shot, you can feel the desolation, but the sun and mountains in the distance contradict.  I love it.', '2007-08-18 18:05:17.000000', NULL, 1),
(4009572, 570813, 82937, '<td valign="top">Maybe better in color?</td>', 'Maybe better in color?', '2007-08-18 18:05:53.000000', NULL, 1),
(4009574, 571380, 82937, '<td valign="top">Very nice, just wish the sky were blue, but I guess that''s not the look you were going for.</td>', 'Very nice, just wish the sky were blue, but I guess that''s not the look you were going for.', '2007-08-18 18:07:04.000000', NULL, 1),
(4009576, 570889, 82937, '<td valign="top">Nice shot, wish the background was clearer.</td>', 'Nice shot, wish the background was clearer.', '2007-08-18 18:07:47.000000', NULL, 1),
(4009577, 570974, 82937, '<td valign="top">Run for cover!  Love this.</td>', 'Run for cover!  Love this.', '2007-08-18 18:08:17.000000', NULL, 1),
(4009578, 571667, 82937, '<td valign="top">No specific point of interest here.</td>', 'No specific point of interest here.', '2007-08-18 18:08:48.000000', NULL, 1),
(4009579, 571771, 82937, '<td valign="top">Clear, crisp and I can smell the corn.</td>', 'Clear, crisp and I can smell the corn.', '2007-08-18 18:09:12.000000', NULL, 1),
(4009580, 571832, 82937, '<td valign="top">Wow.  I don''t know why, but it speaks to me.</td>', 'Wow.  I don''t know why, but it speaks to me.', '2007-08-18 18:10:09.000000', NULL, 1),
(4009582, 570117, 82937, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2007-08-18 18:10:22.000000', NULL, 1),
