(4009587, 571266, 82937, '<td valign="top">I feel like I''m there.</td>', 'I feel like I''m there.', '2007-08-18 18:13:49.000000', NULL, 1),
(4009590, 572001, 82937, '<td valign="top">Nice shot, wish you could move the branches though.</td>', 'Nice shot, wish you could move the branches though.', '2007-08-18 18:16:31.000000', NULL, 1),
(4009591, 569751, 82937, '<td valign="top">Very, very rural!</td>', 'Very, very rural!', '2007-08-18 18:16:54.000000', NULL, 1),
