(4009600, 571425, 82937, '<td valign="top">So peaceful.</td>', 'So peaceful.', '2007-08-18 18:20:21.000000', NULL, 1),
(4009603, 571905, 62249, '<td valign="top">Great shot. Moody, well exposed, well composed.</td>', 'Great shot. Moody, well exposed, well composed.', '2007-08-18 18:21:04.000000', NULL, 1),
(4009604, 569261, 62249, '<td valign="top">Great capture, great lighting. A really good photo.</td>', 'Great capture, great lighting. A really good photo.', '2007-08-18 18:21:12.000000', NULL, 1),
(4009607, 571047, 82937, '<td valign="top">Nice, but I''d like to see it close up!</td>', 'Nice, but I''d like to see it close up!', '2007-08-18 18:25:45.000000', NULL, 1),
(4009608, 570937, 82937, '<td valign="top">Stunning!</td>', 'Stunning!', '2007-08-18 18:26:09.000000', NULL, 1),
(4009611, 569891, 82937, '<td valign="top">Love the photo, but not the title.  Seems like it''s more about the greenery.</td>', 'Love the photo, but not the title.  Seems like it''s more about the greenery.', '2007-08-18 18:27:38.000000', NULL, 1),
