(4012999, 570085, 82814, '<td valign="top">I was already singing that song in my head before I read your caption.  Perfect moment captured here.</td>', 'I was already singing that song in my head before I read your caption.  Perfect moment captured here.', '2007-08-20 01:58:52.000000', NULL, 1),
(4013022, 571939, 82814, '<td valign="top">Oh my, how perfect is this?  Please remember to scatter my ashes here when my time is up.  I could stare at this for a long time and not get bored of the colours or the texture.</td>', 'Oh my, how perfect is this?  Please remember to scatter my ashes here when my time is up.  I could stare at this for a long time and not get bored of the colours or the texture.', '2007-08-20 02:03:15.000000', NULL, 1),
(4013026, 571148, 82814, '<td valign="top">Have you seen Toto and Dorothy around?  They should have landed here somewhere.  Wonderful capture here.  Looks like this structure has survived a few twisters in it''s day.</td>', 'Have you seen Toto and Dorothy around?  They should have landed here somewhere.  Wonderful capture here.  Looks like this structure has survived a few twisters in it''s day.', '2007-08-20 02:05:11.000000', NULL, 1),
