(4015296, 572004, 70181, '<td valign="top">I like this one.  Beyond the great capture of the double rainbow, you''ve got an interesting foreground with movement of the tall grass.  Great colors.  The grass in the foreground almost looks surreal in color and texture.  It''s a photo that could easily make a beautiful oil painting.</td>', 'I like this one.  Beyond the great capture of the double rainbow, you''ve got an interesting foreground with movement of the tall grass.  Great colors.  The grass in the foreground almost looks surreal in color and texture.  It''s a photo that could easily make a beautiful oil painting.', '2007-08-20 18:11:15.000000', NULL, 1),
(4015297, 571968, 70181, '<td valign="top">Wow, what a sky.  Fantastic colors and very dramatic.  Great silhouette.</td>', 'Wow, what a sky.  Fantastic colors and very dramatic.  Great silhouette.', '2007-08-20 18:11:21.000000', NULL, 1),
(4015298, 571762, 70181, '<td valign="top">Perfect title.  Love the colors.  And such an interesting sky.</td>', 'Perfect title.  Love the colors.  And such an interesting sky.', '2007-08-20 18:11:28.000000', NULL, 1),
(4015299, 571114, 70181, '<td valign="top">Very nice.  Good sharpness, interesting sky.  Interesting photo overall.</td>', 'Very nice.  Good sharpness, interesting sky.  Interesting photo overall.', '2007-08-20 18:11:32.000000', NULL, 1),
(4015300, 570611, 70181, '<td valign="top">Very dramatic sky.  Nice use of the vertical orientation.</td>', 'Very dramatic sky.  Nice use of the vertical orientation.', '2007-08-20 18:11:35.000000', NULL, 1),
(4015301, 571117, 70181, '<td valign="top">Only one negative from me - the color looks just a tad overdone.  But plenty of positives - great composition, interesting subject, gorgeous sky.</td>', 'Only one negative from me - the color looks just a tad overdone.  But plenty of positives - great composition, interesting subject, gorgeous sky.', '2007-08-20 18:11:40.000000', NULL, 1),
(4015302, 569347, 70181, '<td valign="top">Good use of the foreground elements.  Nice composition.  The photo tells a story.  Looks like a beautiful place to visit.  Great job.</td>', 'Good use of the foreground elements.  Nice composition.  The photo tells a story.  Looks like a beautiful place to visit.  Great job.', '2007-08-20 18:11:45.000000', NULL, 1),
(4015303, 568493, 70181, '<td valign="top">Beautiful blue in the sky.  I like the way the trail leads the viewer to the person in the center.  And the lighting is nice, the darkened trees on the edges of the photo also highlight the center.</td>', 'Beautiful blue in the sky.  I like the way the trail leads the viewer to the person in the center.  And the lighting is nice, the darkened trees on the edges of the photo also highlight the center.', '2007-08-20 18:11:48.000000', NULL, 1),
(4015304, 568549, 70181, '<td valign="top">Very nice composition.  Good use of depth of field to make an interesting shot.</td>', 'Very nice composition.  Good use of depth of field to make an interesting shot.', '2007-08-20 18:11:51.000000', NULL, 1),
(4015305, 569879, 70181, '<td valign="top">Great colors.  Very nice use of the wide angle distortion to create a very interesting shot.</td>', 'Great colors.  Very nice use of the wide angle distortion to create a very interesting shot.', '2007-08-20 18:11:56.000000', NULL, 1),
(4015306, 568197, 70181, '<td valign="top">Interesting shot.  Great sharpness throughout  I like the processing.</td>', 'Interesting shot.  Great sharpness throughout  I like the processing.', '2007-08-20 18:11:59.000000', NULL, 1),
(4015308, 571136, 70181, '<td valign="top">Great clarity.  Beautiful colors, interesting sky.  Nice composition.  I like it.</td>', 'Great clarity.  Beautiful colors, interesting sky.  Nice composition.  I like it.', '2007-08-20 18:12:04.000000', NULL, 1),
(4015309, 569391, 70181, '<td valign="top">What a great sky for that setting.  Beautiful colors and nice composition.</td>', 'What a great sky for that setting.  Beautiful colors and nice composition.', '2007-08-20 18:12:08.000000', NULL, 1),
(4015310, 571706, 70181, '<td valign="top">Stunning capture.  Great timing.</td>', 'Stunning capture.  Great timing.', '2007-08-20 18:12:17.000000', NULL, 1),
(4015311, 568935, 70181, '<td valign="top">Interesting perspective.  Good color and perfect depth of field.</td>', 'Interesting perspective.  Good color and perfect depth of field.', '2007-08-20 18:12:20.000000', NULL, 1),
(4015312, 570970, 70181, '<td valign="top">Beautiful deep blue sky with great clouds.  Nice composition and use of the lines of the road and fence.</td>', 'Beautiful deep blue sky with great clouds.  Nice composition and use of the lines of the road and fence.', '2007-08-20 18:12:24.000000', NULL, 1),
(4015313, 570453, 70181, '<td valign="top">Exactly what comes to mind when I hear "rural landscape."  Great sharpness, nice composition and good looking sky.</td>', 'Exactly what comes to mind when I hear "rural landscape."  Great sharpness, nice composition and good looking sky.', '2007-08-20 18:12:27.000000', NULL, 1),
(4015314, 569261, 70181, '<td valign="top">Now that looks like fun.  Gorgeous setting and perfect capture of the light.</td>', 'Now that looks like fun.  Gorgeous setting and perfect capture of the light.', '2007-08-20 18:12:32.000000', NULL, 1),
(4015384, 570974, 83034, '<td valign="top">Great Photograph, Very well done!  The birds are good but a little distracting.</td>', 'Great Photograph, Very well done!  The birds are good but a little distracting.', '2007-08-20 18:53:06.000000', NULL, 1),
(4015493, 570974, 83032, '<td valign="top">Very nice lighting.</td>', 'Very nice lighting.', '2007-08-20 19:45:49.000000', NULL, 1),
