(4015568, 571047, 81852, '<td valign="top">Can hardly see the cemetary.</td>', 'Can hardly see the cemetary.', '2007-08-20 20:21:15.000000', NULL, 1),
(4015573, 570758, 81852, '<td valign="top">The branch totally cuts off the view of the house. My eyes keep traveling up the photo towards the house and then I can''t see it.</td>', 'The branch totally cuts off the view of the house. My eyes keep traveling up the photo towards the house and then I can''t see it.', '2007-08-20 20:23:16.000000', NULL, 1),
(4015605, 568741, 81852, '<td valign="top">The legs of the bug are the only part in focus.</td>', 'The legs of the bug are the only part in focus.', '2007-08-20 20:34:29.000000', NULL, 1),
(4015611, 570706, 81852, '<td valign="top">Just really hard to look at.</td>', 'Just really hard to look at.', '2007-08-20 20:37:33.000000', NULL, 1),
(4015612, 570752, 81852, '<td valign="top">The horse is in shadows, the forehead is blown out. The tree and fence just feel like they are in the way.</td>', 'The horse is in shadows, the forehead is blown out. The tree and fence just feel like they are in the way.', '2007-08-20 20:39:30.000000', NULL, 1),
(4015626, 568922, 22970, '<td valign="top">nice focus on the turtle but not large enough to give the overall picture the feeling of being in focus. I find myself drawn to the oof areas. Being a tight shot does not give me a real sense of rural landscape. I feel a larger field of view and more of the surrounding in focus could of improved your photograph. ~Wish you the best in the challenge (4).</td>', 'nice focus on the turtle but not large enough to give the overall picture the feeling of being in focus. I find myself drawn to the oof areas. Being a tight shot does not give me a real sense of rural landscape. I feel a larger field of view and more of the surrounding in focus could of improved your photograph. ~Wish you the best in the challenge (4).', '2007-08-20 20:45:32.000000', NULL, 1),
(4015632, 571777, 81852, '<td valign="top">Wrong challenge.</td>', 'Wrong challenge.', '2007-08-20 20:47:20.000000', NULL, 1),
