INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4016650, 569388, 74102, '<td valign="top">I have tried to do do that viaduct loads of times, good shot.</td>', 'I have tried to do do that viaduct loads of times, good shot.', '2007-08-21 06:21:42.000000', NULL, 1),
(4016701, 571376, 83053, '<td valign="top">i dont see landscape in this photo!</td>', 'i dont see landscape in this photo!', '2007-08-21 06:57:11.000000', NULL, 1),
(4016894, 570993, 31885, '<td valign="top">Wow, this is absolutely stunning! The detail is amazing, right into the furthest corner. I would love to see a huge print of this.</td>', 'Wow, this is absolutely stunning! The detail is amazing, right into the furthest corner. I would love to see a huge print of this.', '2007-08-21 09:36:30.000000', NULL, 1),
(4016896, 571311, 31885, '<td valign="top">Too much JPG compression - the details have been lost. It looks like the original could be quite nice, though.</td>', 'Too much JPG compression - the details have been lost. It looks like the original could be quite nice, though.', '2007-08-21 09:39:30.000000', NULL, 1),
(4016900, 571668, 31885, '<td valign="top">I like the composition, nice point of view.</td>', 'I like the composition, nice point of view.', '2007-08-21 09:44:55.000000', NULL, 1),
(4016908, 570941, 31885, '<td valign="top">Just slightly over the top for me. I see it has been validated - maybe I don''t understand the rules completely. Would love to know how you did this inside the challenge rules.</td>', 'Just slightly over the top for me. I see it has been validated - maybe I don''t understand the rules completely. Would love to know how you did this inside the challenge rules.', '2007-08-21 09:49:16.000000', NULL, 1),
(4016911, 571988, 31885, '<td valign="top">I like the effect, well done!</td>', 'I like the effect, well done!', '2007-08-21 09:49:54.000000', NULL, 1),
(4016912, 571863, 83053, '<td valign="top">nice photo</td>', 'nice photo', '2007-08-21 09:51:08.000000', NULL, 1),
(4016916, 572001, 31885, '<td valign="top">Strong composition and colouring.</td>', 'Strong composition and colouring.', '2007-08-21 09:52:40.000000', NULL, 1),
(4016918, 571292, 83053, '<td valign="top">sure it well</td>', 'sure it well', '2007-08-21 09:52:59.000000', NULL, 1),
(4016922, 569388, 31885, '<td valign="top">The details are just a tad too dark. I like the dramatic feel.</td>', 'The details are just a tad too dark. I like the dramatic feel.', '2007-08-21 09:54:07.000000', NULL, 1),
(4016941, 569261, 31885, '<td valign="top">Wow, great ligting!</td>', 'Wow, great ligting!', '2007-08-21 10:04:54.000000', NULL, 1),
(4017063, 568343, 76430, '<td valign="top">Wow, this is really sharp despite the bright sun.  Great sun rays.  9</td>', 'Wow, this is really sharp despite the bright sun.  Great sun rays.  9', '2007-08-21 11:05:06.000000', NULL, 1),
(4017064, 568278, 76430, '<td valign="top">Beautiful scene.  I''d like to see this full resolution.</td>', 'Beautiful scene.  I''d like to see this full resolution.', '2007-08-21 11:05:31.000000', NULL, 1),
(4017065, 570427, 76430, '<td valign="top">Nice saturation and composition</td>', 'Nice saturation and composition', '2007-08-21 11:05:37.000000', NULL, 1),
(4017070, 571678, 76430, '<td valign="top">Great silouettes of the deer against the fog bank.  It looks like you converted to sepia.  That''s fine, but I''d just like to see what it looks like in full color with saturated grass and sky.  8</td>', 'Great silouettes of the deer against the fog bank.  It looks like you converted to sepia.  That''s fine, but I''d just like to see what it looks like in full color with saturated grass and sky.  8', '2007-08-21 11:10:55.000000', NULL, 1),
(4017073, 571731, 76430, '<td valign="top">Nice deep DOF.  I like how the contours of the horse sort of follow the contours of the hills.</td>', 'Nice deep DOF.  I like how the contours of the horse sort of follow the contours of the hills.', '2007-08-21 11:13:31.000000', NULL, 1),
(4017079, 572001, 76430, '<td valign="top">You broke the "rule" by bisecting the picture with the horizon.  Still it''s a nice sky and ground scene.  Very sharp and leasing colors.</td>', 'You broke the "rule" by bisecting the picture with the horizon.  Still it''s a nice sky and ground scene.  Very sharp and leasing colors.', '2007-08-21 11:17:03.000000', NULL, 1),
(4017097, 571762, 76430, '<td valign="top">Beautiful Grand Canyon view, excellent color saturation and little puffy clouds, nice framing of the side with the tree.  Just one minor nitpik, I think if you stepped closer to the edge, got rid of most of the tan rock on the edge that takes up a lot of the shot, and replaced it with more canyon it would improve it.</td>', 'Beautiful Grand Canyon view, excellent color saturation and little puffy clouds, nice framing of the side with the tree.  Just one minor nitpik, I think if you stepped closer to the edge, got rid of most of the tan rock on the edge that takes up a lot of the shot, and replaced it with more canyon it would improve it.', '2007-08-21 11:24:22.000000', NULL, 1),
(4017114, 569111, 42100, '<td valign="top">Great leading lines...almost spiritual in the way you chose to present this photograph.  Very well done!</td>', 'Great leading lines...almost spiritual in the way you chose to present this photograph.  Very well done!', '2007-08-21 11:29:36.000000', NULL, 1),
(4017119, 571846, 42100, '<td valign="top">Very nice photo...this looks like fine art lifted right from the 1930''s or so.  Well done!</td>', 'Very nice photo...this looks like fine art lifted right from the 1930''s or so.  Well done!', '2007-08-21 11:30:47.000000', NULL, 1),
(4017120, 569261, 81609, '<td valign="top">To me this is the best. Just too beautiful.</td>', 'To me this is the best. Just too beautiful.', '2007-08-21 11:31:26.000000', NULL, 1),
(4017124, 571832, 42100, '<td valign="top">Unique and unusual toning...it really fits this scene and I think it looks great.  Nicely done!</td>', 'Unique and unusual toning...it really fits this scene and I think it looks great.  Nicely done!', '2007-08-21 11:33:12.000000', NULL, 1),
(4017153, 572005, 83053, '<td valign="top">great shot.</td>', 'great shot.', '2007-08-21 11:59:31.000000', NULL, 1),
(4017155, 569261, 83053, '<td valign="top">nice photo.</td>', 'nice photo.', '2007-08-21 12:00:09.000000', NULL, 1),
(4017166, 571315, 82749, '<td valign="top">Forground could be improved by being lighter and brighter</td>', 'Forground could be improved by being lighter and brighter', '2007-08-21 12:08:42.000000', NULL, 1),
(4017170, 569301, 42100, '<td valign="top">Great color and clarity...the horse really pops against that background.  The fence makes a very good leading line, but at the same time seems a bit unsettling...so I guess I''m on the fence about the inclusion of the fence.</td>', 'Great color and clarity...the horse really pops against that background.  The fence makes a very good leading line, but at the same time seems a bit unsettling...so I guess I''m on the fence about the inclusion of the fence.', '2007-08-21 12:14:25.000000', NULL, 1),
(4017184, 569384, 42100, '<td valign="top">A wide sweeping landscape...but in my mind it''s more of an abstract or even a macro with all the great texture and patterns.  Very nice!</td>', 'A wide sweeping landscape...but in my mind it''s more of an abstract or even a macro with all the great texture and patterns.  Very nice!', '2007-08-21 12:44:32.000000', NULL, 1),
(4017187, 571142, 42100, '<td valign="top">I like the original and creative composition.  The warm lighting is very endearing.  Nicely done!</td>', 'I like the original and creative composition.  The warm lighting is very endearing.  Nicely done!', '2007-08-21 12:46:36.000000', NULL, 1),
(4017190, 570991, 42100, '<td valign="top">Beautiful light and reflection...the composition is interesting and dynamic as well.  Great job!</td>', 'Beautiful light and reflection...the composition is interesting and dynamic as well.  Great job!', '2007-08-21 12:48:13.000000', NULL, 1),
(4017195, 568343, 42100, '<td valign="top">The light breaking through that forest is beautiful.  It would make an amazing photo with that portion alone.  Great job!</td>', 'The light breaking through that forest is beautiful.  It would make an amazing photo with that portion alone.  Great job!', '2007-08-21 12:50:16.000000', NULL, 1),
(4017197, 571114, 42100, '<td valign="top">Dramatic sky and fascinating old structure...makes for a dynamic combination.  Very nice!</td>', 'Dramatic sky and fascinating old structure...makes for a dynamic combination.  Very nice!', '2007-08-21 12:51:12.000000', NULL, 1),
(4017201, 568315, 42100, '<td valign="top">Mystical and magical with that fog...and the red tones are very warm and inviting.  Excellent!</td>', 'Mystical and magical with that fog...and the red tones are very warm and inviting.  Excellent!', '2007-08-21 12:52:24.000000', NULL, 1),
(4017205, 572007, 42100, '<td valign="top">Awesome light...and you made the most of it with this well composed photo.  Very well done!</td>', 'Awesome light...and you made the most of it with this well composed photo.  Very well done!', '2007-08-21 12:53:57.000000', NULL, 1),
(4017238, 570788, 42100, '<td valign="top">The big sky and the sense of freedom captured well...I suspect that''s exactly what a lot of farmers love about the life of farming.  Well done!</td>', 'The big sky and the sense of freedom captured well...I suspect that''s exactly what a lot of farmers love about the life of farming.  Well done!', '2007-08-21 13:17:17.000000', NULL, 1),
