(4017991, 568343, 65319, '<td valign="top">His soul fragmented by time<br/>Shredded by shadows and dreams<br/>Looking over his shoulder<br/>Life is not what it seems<br/> <br/>Dark sleep for a time<br/>Come and rest for a while<br/>Weariness creeps to the bone<br/>The last onethe longest mile<br/> <br/>Awakening to a Promised Land<br/>Outwitting Deaths dark and untimely demise<br/>Triumphant, as he beheld <br/>A far green country under a swift sunrise<br/><br/><br/><i>Message edited by author 2007-08-28 11:34:40.</i></td>', 'His soul fragmented by timeShredded by shadows and dreamsLooking over his shoulderLife is not what it seems Dark sleep for a timeCome and rest for a whileWeariness creeps to the boneThe last onethe longest mile Awakening to a Promised LandOutwitting Deaths dark and untimely demiseTriumphant, as he beheld A far green country under a swift sunrise', '2007-08-21 18:03:23.000000', '2007-08-28 12:34:40.000000', 1),
(4018029, 571830, 80867, '<td valign="top">The sharpness added to this makes it unreal. Great location though. I would go back.</td>', 'The sharpness added to this makes it unreal. Great location though. I would go back.', '2007-08-21 18:23:09.000000', NULL, 1),
(4018032, 568793, 80867, '<td valign="top">Simply great.</td>', 'Simply great.', '2007-08-21 18:23:47.000000', NULL, 1),
(4018038, 571678, 80867, '<td valign="top">Great shot. the path in the foreground leads you right to them.</td>', 'Great shot. the path in the foreground leads you right to them.', '2007-08-21 18:24:33.000000', NULL, 1),
(4018039, 570764, 80867, '<td valign="top">Great..</td>', 'Great..', '2007-08-21 18:24:42.000000', NULL, 1),
(4018041, 572003, 18197, '<td valign="top">Love the Route 66 metaphore! The photo not so much.</td>', 'Love the Route 66 metaphore! The photo not so much.', '2007-08-21 18:24:54.000000', NULL, 1),
(4018044, 571403, 18197, '<td valign="top">Great idea! But feels flat and unfocused to me.</td>', 'Great idea! But feels flat and unfocused to me.', '2007-08-21 18:26:14.000000', NULL, 1),
(4018046, 571796, 79357, '<td valign="top">The picture lacks a farmer, a pig, a black rain cloud or a sun flower. It is a little boring.</td>', 'The picture lacks a farmer, a pig, a black rain cloud or a sun flower. It is a little boring.', '2007-08-21 18:26:25.000000', NULL, 1),
