(4018065, 571735, 18197, '<td valign="top">Love the stars ... they add a lot to the photo. Good job.</td>', 'Love the stars ... they add a lot to the photo. Good job.', '2007-08-21 18:29:35.000000', NULL, 1),
(4018068, 571843, 18197, '<td valign="top">Why am I remembering Garison Kieler''s "Cows with Guns" song??!!?? It''s a little intense, a bit too much so for my taste.</td>', 'Why am I remembering Garison Kieler''s "Cows with Guns" song??!!?? It''s a little intense, a bit too much so for my taste.', '2007-08-21 18:31:00.000000', NULL, 1),
(4018075, 570236, 79357, '<td valign="top">looks like the Windows XP standard desktop background haha!</td>', 'looks like the Windows XP standard desktop background haha!', '2007-08-21 18:34:55.000000', NULL, 1),
(4018078, 571983, 18197, '<td valign="top">Not really a landscape but a great photo. I like that the bird is setting on a power pole, insulator included. I have seen this often and like that you''ve shown us this! Focus is good but could be better. Contrast is good generally, but could be better on the bird.</td>', 'Not really a landscape but a great photo. I like that the bird is setting on a power pole, insulator included. I have seen this often and like that you''ve shown us this! Focus is good but could be better. Contrast is good generally, but could be better on the bird.', '2007-08-21 18:35:25.000000', NULL, 1),
(4018080, 571954, 82034, '<td valign="top">Beatiful clouds!  Great photo.</td>', 'Beatiful clouds!  Great photo.', '2007-08-21 18:36:19.000000', NULL, 1),
(4018082, 571939, 82034, '<td valign="top">Amazing colors!</td>', 'Amazing colors!', '2007-08-21 18:36:56.000000', NULL, 1),
(4018086, 571458, 18197, '<td valign="top">To be honest, I love the photo but am confused by the title.</td>', 'To be honest, I love the photo but am confused by the title.', '2007-08-21 18:38:42.000000', NULL, 1),
(4018095, 571136, 18197, '<td valign="top">A bit too intense for me. But a nice capture and presentatiopn.</td>', 'A bit too intense for me. But a nice capture and presentatiopn.', '2007-08-21 18:41:51.000000', NULL, 1),
(4018102, 571025, 18197, '<td valign="top">I was here today (21 Aug 2007). Beautiful site (and beautiful country I might add), but you''ve lost much of the detail and texture I have come to appreciate.</td>', 'I was here today (21 Aug 2007). Beautiful site (and beautiful country I might add), but you''ve lost much of the detail and texture I have come to appreciate.', '2007-08-21 18:43:43.000000', NULL, 1),
(4018107, 571244, 63398, '<td valign="top">Very nice!</td>', 'Very nice!', '2007-08-21 18:44:51.000000', NULL, 1),
(4018112, 568960, 18197, '<td valign="top">Very moody emotional setting. Well done. However, the subject doesn''t hold my interest.</td>', 'Very moody emotional setting. Well done. However, the subject doesn''t hold my interest.', '2007-08-21 18:45:46.000000', NULL, 1),
(4018117, 570035, 18197, '<td valign="top">Great lighting! Mediocre context.</td>', 'Great lighting! Mediocre context.', '2007-08-21 18:46:27.000000', NULL, 1),
(4018119, 570393, 18197, '<td valign="top">I would like this better if the focus were sharper. Good focus on the post, but weak otherwise.</td>', 'I would like this better if the focus were sharper. Good focus on the post, but weak otherwise.', '2007-08-21 18:47:24.000000', NULL, 1),
(4018126, 568253, 18197, '<td valign="top">A worthy subject but feels flat to me. Try increasing mid-tone contrast.</td>', 'A worthy subject but feels flat to me. Try increasing mid-tone contrast.', '2007-08-21 18:49:07.000000', NULL, 1),
(4018130, 568343, 18197, '<td valign="top">One of the best of the challenge. Light streaming through the trees is terrific! Color saturation is very good. Hope this ribbons.</td>', 'One of the best of the challenge. Light streaming through the trees is terrific! Color saturation is very good. Hope this ribbons.', '2007-08-21 18:50:19.000000', NULL, 1),
(4018132, 568908, 18197, '<td valign="top">Workmanlike photo but fails to hold my interest.</td>', 'Workmanlike photo but fails to hold my interest.', '2007-08-21 18:50:43.000000', NULL, 1),
(4018136, 569108, 18197, '<td valign="top">I LOVE this! Well conceived. Well presented. I grew up in this sort of setting and this speaks to me!</td>', 'I LOVE this! Well conceived. Well presented. I grew up in this sort of setting and this speaks to me!', '2007-08-21 18:52:15.000000', NULL, 1),
(4018139, 571376, 18197, '<td valign="top">Not a rural landscape, IMO. Otherwise a workmanlike photo.</td>', 'Not a rural landscape, IMO. Otherwise a workmanlike photo.', '2007-08-21 18:52:56.000000', NULL, 1),
(4018144, 571364, 18197, '<td valign="top">What a wonderful subject. I have taken photos of similar cows on the Isle of <br/>Skye and really feel close to them. That being said, it feels more like a portrait than a rural landscape.</td>', 'What a wonderful subject. I have taken photos of similar cows on the Isle of Skye and really feel close to them. That being said, it feels more like a portrait than a rural landscape.', '2007-08-21 18:55:11.000000', NULL, 1),
