(4018179, 570303, 18197, '<td valign="top">I love the focus on the grain!!!</td>', 'I love the focus on the grain!!!', '2007-08-21 19:09:31.000000', NULL, 1),
(4018181, 570974, 18197, '<td valign="top">Obviously, a dramatic sky which I like. Well done! If we had advanced editing, I''d like to see the foreground brightened up a bit.</td>', 'Obviously, a dramatic sky which I like. Well done! If we had advanced editing, I''d like to see the foreground brightened up a bit.', '2007-08-21 19:11:06.000000', NULL, 1),
