(4018193, 571678, 18197, '<td valign="top">Wonderful sense of context. I love the lighting and the focus on the grass. Very nice sillouettes. Great background!!! Best of challenge so far for me.</td>', 'Wonderful sense of context. I love the lighting and the focus on the grass. Very nice sillouettes. Great background!!! Best of challenge so far for me.', '2007-08-21 19:18:29.000000', NULL, 1),
(4018195, 571905, 18197, '<td valign="top">Innovative framing. Well done. I like this a lot.</td>', 'Innovative framing. Well done. I like this a lot.', '2007-08-21 19:19:04.000000', NULL, 1),
(4018204, 568493, 18197, '<td valign="top">Road/path rescues the photo. Nice job.</td>', 'Road/path rescues the photo. Nice job.', '2007-08-21 19:22:30.000000', NULL, 1),
(4018210, 571311, 18197, '<td valign="top">I would like this better if the focus were stronger.</td>', 'I would like this better if the focus were stronger.', '2007-08-21 19:23:21.000000', NULL, 1),
(4018212, 571056, 18197, '<td valign="top">Does not really say "rural landscape" to me.</td>', 'Does not really say "rural landscape" to me.', '2007-08-21 19:24:21.000000', NULL, 1),
(4018225, 570574, 18197, '<td valign="top">Nice photo but better if you had straightened the photo.</td>', 'Nice photo but better if you had straightened the photo.', '2007-08-21 19:29:49.000000', NULL, 1),
(4018234, 571938, 18197, '<td valign="top">Having trouble finding "rural landscape" in this. And btw, I don''t care what ducks cost.</td>', 'Having trouble finding "rural landscape" in this. And btw, I don''t care what ducks cost.', '2007-08-21 19:32:14.000000', NULL, 1),
