(4018250, 571674, 18197, '<td valign="top">Sorry, tired of the hay bale genre ... and this isn''t hte best of breed.</td>', 'Sorry, tired of the hay bale genre ... and this isn''t hte best of breed.', '2007-08-21 19:39:38.000000', NULL, 1),
(4018258, 570818, 18197, '<td valign="top">Fantastic photo. Nicely saturated. Well captured and presented. But doesn''t feel like it meets the challenge.</td>', 'Fantastic photo. Nicely saturated. Well captured and presented. But doesn''t feel like it meets the challenge.', '2007-08-21 19:41:47.000000', NULL, 1),
(4018274, 571830, 18197, '<td valign="top">Post processing distracts ... especially the halo over the hils. Easy does it!!</td>', 'Post processing distracts ... especially the halo over the hils. Easy does it!!', '2007-08-21 19:45:48.000000', NULL, 1),
