(4018312, 571380, 18197, '<td valign="top">A bit too bright for my taste a very (very) orange.</td>', 'A bit too bright for my taste a very (very) orange.', '2007-08-21 19:52:40.000000', NULL, 1),
(4018322, 570104, 78021, '<td valign="top">Way too bright.</td>', 'Way too bright.', '2007-08-21 19:54:33.000000', NULL, 1),
