(4018356, 571354, 18197, '<td valign="top">Zooming mush. Not to my taste. But credit for out-of-the-box image.</td>', 'Zooming mush. Not to my taste. But credit for out-of-the-box image.', '2007-08-21 19:59:43.000000', NULL, 1),
(4018362, 569352, 18197, '<td valign="top">Not being English ... I can resonate with the quote more so than the image.</td>', 'Not being English ... I can resonate with the quote more so than the image.', '2007-08-21 20:01:21.000000', NULL, 1),
(4018374, 570870, 78021, '<td valign="top">DOF so shallow no significant portion of the shot is in focus.  Was this takeken with a mirror lens? ("donut bokeh") An interesting effect with the dew, but the effect would be nicer if a greater portion of the scene was in focus enough to see some of the dew in focus.</td>', 'DOF so shallow no significant portion of the shot is in focus.  Was this takeken with a mirror lens? ("donut bokeh") An interesting effect with the dew, but the effect would be nicer if a greater portion of the scene was in focus enough to see some of the dew in focus.', '2007-08-21 20:04:08.000000', NULL, 1),
(4018382, 569996, 18197, '<td valign="top">Beautiful image of a cowboy with an IQ of perhaps 55. I grew up in the western US an I am sad that this photo might be taken as representative of the west.</td>', 'Beautiful image of a cowboy with an IQ of perhaps 55. I grew up in the western US an I am sad that this photo might be taken as representative of the west.', '2007-08-21 20:05:17.000000', NULL, 1),
(4018404, 571731, 18197, '<td valign="top">I hope it''s sleeping, else negative scores would be appropriate. Technically excellent photo ... lighting, colors, contrast, focus, composition, presentation ...</td>', 'I hope it''s sleeping, else negative scores would be appropriate. Technically excellent photo ... lighting, colors, contrast, focus, composition, presentation ...', '2007-08-21 20:09:26.000000', NULL, 1),
(4018410, 570870, 18197, '<td valign="top">For me, just a snap of an uninteresting subject ... otherwise a very nice abstract.</td>', 'For me, just a snap of an uninteresting subject ... otherwise a very nice abstract.', '2007-08-21 20:10:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4018418, 570974, 82749, '<td valign="top">Nice contrast of colors, and of lines vs curves</td>', 'Nice contrast of colors, and of lines vs curves', '2007-08-21 20:13:12.000000', NULL, 1),
(4018421, 570393, 78021, '<td valign="top">Nice composition, but the sky is overexposed.  Had you taken the shot a stop or two darker, and adjusted "curves" to brighten mid and dark tones, you might have ended up with a very nice looking sky.</td>', 'Nice composition, but the sky is overexposed.  Had you taken the shot a stop or two darker, and adjusted "curves" to brighten mid and dark tones, you might have ended up with a very nice looking sky.', '2007-08-21 20:13:43.000000', NULL, 1),
(4018423, 568315, 82749, '<td valign="top">Excellent colors and mist</td>', 'Excellent colors and mist', '2007-08-21 20:13:55.000000', NULL, 1),
(4018427, 568549, 82749, '<td valign="top">Composition is nice, but focus on haystack in the front could be better</td>', 'Composition is nice, but focus on haystack in the front could be better', '2007-08-21 20:15:18.000000', NULL, 1),
(4018435, 569261, 78021, '<td valign="top">Great shot! ...but I''m not sure how this is a landscape?</td>', 'Great shot! ...but I''m not sure how this is a landscape?', '2007-08-21 20:18:04.000000', NULL, 1),
(4018452, 569879, 78021, '<td valign="top">Vary nice composition using the fisheye. :-)  The sky seems either over-exposed, or over-photoshopped (or both?). The rest of the composition is suprizingly sharp everywhere. 6.</td>', 'Vary nice composition using the fisheye. :-)  The sky seems either over-exposed, or over-photoshopped (or both?). The rest of the composition is suprizingly sharp everywhere. 6.', '2007-08-21 20:25:41.000000', NULL, 1),
(4018464, 571315, 78021, '<td valign="top">Nice composition, but the land is too dark, and the sky is too bright.  Use of "Curves" in a tool like PhotoShop or Paint.net (free) could have lightened up the mid and dark tones (the land) while darkening the light times (sky) at the same time...resulting in more ballanced lighting in the picture. //www.cambridgeincolour.com/tutorials/photoshop-curves.htm</td>', 'Nice composition, but the land is too dark, and the sky is too bright.  Use of "Curves" in a tool like PhotoShop or Paint.net (free) could have lightened up the mid and dark tones (the land) while darkening the light times (sky) at the same time...resulting in more ballanced lighting in the picture. //www.cambridgeincolour.com/tutorials/photoshop-curves.htm', '2007-08-21 20:32:23.000000', NULL, 1),
(4018474, 571755, 78021, '<td valign="top">Nice colors! :-)</td>', 'Nice colors! :-)', '2007-08-21 20:35:20.000000', NULL, 1),
(4018490, 568793, 78021, '<td valign="top">The TV style "Letterbox" frame gives the a nice effect to exagerate the panoramic style of this landscape.  Nice.</td>', 'The TV style "Letterbox" frame gives the a nice effect to exagerate the panoramic style of this landscape.  Nice.', '2007-08-21 20:43:52.000000', NULL, 1),
(4018511, 571983, 78021, '<td valign="top">Nice picture...but there isn''t even any land in this "landscape".</td>', 'Nice picture...but there isn''t even any land in this "landscape".', '2007-08-21 20:53:10.000000', NULL, 1),
(4018514, 570941, 78021, '<td valign="top">Aswome sky! 10!</td>', 'Aswome sky! 10!', '2007-08-21 20:55:18.000000', NULL, 1),
(4018557, 571458, 81577, '<td valign="top">Harsh title...</td>', 'Harsh title...', '2007-08-21 21:26:18.000000', NULL, 1),
(4018594, 571142, 81577, '<td valign="top">Incredible DOF</td>', 'Incredible DOF', '2007-08-21 21:47:05.000000', NULL, 1),
(4018642, 568278, 30669, '<td valign="top">beautiful</td>', 'beautiful', '2007-08-21 22:15:21.000000', NULL, 1),
(4018645, 571142, 60698, '<td valign="top">Love the red buildings against the soft greens. Ahhhh! I don''t want to leave.</td>', 'Love the red buildings against the soft greens. Ahhhh! I don''t want to leave.', '2007-08-21 22:16:40.000000', NULL, 1),
(4018646, 570807, 60698, '<td valign="top">Wow! Nice leading lines you have there!</td>', 'Wow! Nice leading lines you have there!', '2007-08-21 22:17:16.000000', NULL, 1),
(4018647, 572001, 60698, '<td valign="top">Fabulous find! Nicely done!</td>', 'Fabulous find! Nicely done!', '2007-08-21 22:17:46.000000', NULL, 1),
(4018649, 570393, 83039, '<td valign="top">Beautiful colors.  The sky effect looks great.</td>', 'Beautiful colors.  The sky effect looks great.', '2007-08-21 22:18:34.000000', NULL, 1),
(4018656, 571788, 83039, '<td valign="top">Cool pic, and I''m jealous that I can''t see this place in person :-)  Some the detail seems to be lost and I think you could bump the contrast and saturation up a bit to make things pop out more.</td>', 'Cool pic, and I''m jealous that I can''t see this place in person :-)  Some the detail seems to be lost and I think you could bump the contrast and saturation up a bit to make things pop out more.', '2007-08-21 22:20:38.000000', NULL, 1),
(4018657, 571968, 30669, '<td valign="top">Very clever and well done</td>', 'Very clever and well done', '2007-08-21 22:21:09.000000', NULL, 1),
