(4019384, 568343, 80167, '<td valign="top">I LOVE this photo! Could you maybe write a "How''d they do that" about this photo because I''d love to know how you got so much detail out of the shadows/highlights by only using basic editing.<br/> <br/>Great work!</td>', 'I LOVE this photo! Could you maybe write a "How''d they do that" about this photo because I''d love to know how you got so much detail out of the shadows/highlights by only using basic editing. Great work!', '2007-08-22 02:00:01.000000', NULL, 0),
(4019393, 571841, 66384, '<td valign="top">What a road -- one muddy rut after another. I like this a lot, Terry. Except for the condition of the road, I am very tempted to drive in. I like the colors and composition.</td>', 'What a road -- one muddy rut after another. I like this a lot, Terry. Except for the condition of the road, I am very tempted to drive in. I like the colors and composition.', '2007-08-22 02:01:48.000000', NULL, 0),
