INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4023092, 570758, 82384, '<td valign="top">Thanks so much for all your comments. I love this site. I went back and reshot this pic lower to the ground, as suggested, and was surprised to find I was not happy with the result. As such, my eye definitely shifted away from the tree, which I think is the most interesting subject, to the house.<br/> <br/>Peter H</td>', 'Thanks so much for all your comments. I love this site. I went back and reshot this pic lower to the ground, as suggested, and was surprised to find I was not happy with the result. As such, my eye definitely shifted away from the tree, which I think is the most interesting subject, to the house. Peter H', '2007-08-23 01:44:15.000000', NULL, 0),
